        .m_axis_tuser (rz_tuser)
    );

    axis_image_border_gen #(
        .IMG_WIDTH   (IMG_WIDTH_OUT),
        .IMG_HEIGHT  (IMG_HEIGHT_OUT),
        .BORDER_COLOR(BORDER_COLOR),
        .DATA_WIDTH  (DATA_WIDTH)
    ) border_gen_inst (
        .clk          (clk),
        .resetn       (resetn),
        .s_axis_tdata (rz_tdata),
        .s_axis_tvalid(rz_tvalid),
        .s_axis_tready(rz_tready),
        .s_axis_tlast (rz_tlast),
        .s_axis_tuser (rz_tuser),
        .m_axis_tdata (m_axis_tdata),
        .m_axis_tvalid(m_axis_tvalid),
        .m_axis_tready(m_axis_tready),
        .m_axis_tlast (m_axis_tlast),
        .m_axis_tuser (m_axis_tuser)
    );
endmodule
"}, {"rtl/axis_image_border_gen.sv": "module axis_image_border_gen #(
    parameter IMG_WIDTH    = 5,
    parameter IMG_HEIGHT   = 5,
    parameter BORDER_COLOR = 16'hFFFF,
    parameter DATA_WIDTH   = 16
)(
    input  wire                  clk,
    input  wire                  resetn,
    input  wire [DATA_WIDTH-1:0] s_axis_tdata,
    input  wire                  s_axis_tvalid,
    output wire                  s_axis_tready,
    input  wire                  s_axis_tlast,
    input  wire                  s_axis_tuser,

    output wire [DATA_WIDTH-1:0] m_axis_tdata,
    output wire                  m_axis_tvalid,
    input  wire                  m_axis_tready,
    output wire                  m_axis_tlast,
    output wire                  m_axis_tuser
);
    localparam integer NEEDED = IMG_WIDTH * IMG_HEIGHT;

    reg [DATA_WIDTH-1:0] rz_mem [0:NEEDED-1];

    integer recv_cnt;
    reg     recving;
    reg     out_active;
    integer ox, oy;

    // Accept resized pixels until the buffer is full.
    assign s_axis_tready = resetn & recving;

    wire is_border = (ox == 0) || (ox == IMG_WIDTH + 1) ||
                     (oy == 0) || (oy == IMG_HEIGHT + 1);

    wire [31:0] inner_idx = is_border ? 32'd0
                                      : ((oy - 1) * IMG_WIDTH + (ox - 1));

    assign m_axis_tvalid = out_active;
    assign m_axis_tlast  = out_active && (ox == IMG_WIDTH + 1);
    assign m_axis_tuser  = out_active && (ox == 0) && (oy == 0);
    assign m_axis_tdata  = is_border ? BORDER_COLOR[DATA_WIDTH-1:0]
                                     : rz_mem[inner_idx];

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            recv_cnt   <= 0;
            recving    <= 1'b1;
            out_active <= 1'b0;
            ox         <= 0;
            oy         <= 0;
        end else begin
            // ---- RECEIVE: buffer the resized frame ----
            if (recving && s_axis_tvalid && s_axis_tready) begin
                rz_mem[recv_cnt] <= s_axis_tdata;
                if (recv_cnt == NEEDED-1) begin
                    recving    <= 1'b0;
                    out_active <= 1'b1;
                    ox         <= 0;
                    oy         <= 0;
                end
                recv_cnt <= recv_cnt + 1;
            end

            // ---- OUTPUT: stream the bordered frame ----
            if (out_active && m_axis_tready) begin
                if (ox == IMG_WIDTH + 1) begin
                    ox <= 0;
                    if (oy == IMG_HEIGHT + 1)
                        out_active <= 1'b0; // frame done
                    else
                        oy <= oy + 1;
                end else begin
                    ox <= ox + 1;
                end
            end
        end
    end
endmodule
"}, {"rtl/axis_image_resizer.sv": "module axis_image_resizer #(
    parameter IMG_WIDTH_IN   = 640,
    parameter IMG_HEIGHT_IN  = 480,
    parameter IMG_WIDTH_OUT  = 320,
    parameter IMG_HEIGHT_OUT = 240,
    parameter DATA_WIDTH     = 16
)(
    input  wire                  clk,
    input  wire                  resetn,
    input  wire [DATA_WIDTH-1:0] s_axis_tdata,
    input  wire                  s_axis_tvalid,
    output wire                  s_axis_tready,
    input  wire                  s_axis_tlast,
    input  wire                  s_axis_tuser,

    output reg  [DATA_WIDTH-1:0] m_axis_tdata,
    output reg                   m_axis_tvalid,
    input  wire                  m_axis_tready,
    output reg                   m_axis_tlast,
    output reg                   m_axis_tuser
);
    localparam integer SX        = IMG_WIDTH_IN  / IMG_WIDTH_OUT;
    localparam integer SY        = IMG_HEIGHT_IN / IMG_HEIGHT_OUT;
    localparam integer NX        = (IMG_WIDTH_IN + SX - 1) / SX; // ceil(W_IN/SX)
    localparam integer TOTAL_IN  = IMG_WIDTH_IN * IMG_HEIGHT_IN;
    localparam integer NEEDED    = IMG_WIDTH_OUT * IMG_HEIGHT_OUT;

    reg [DATA_WIDTH-1:0] in_mem [0:TOTAL_IN-1];

    integer in_cnt;
    integer emit_cnt;
    reg     filling;
    reg     emitting;
    integer src_addr;

    // Accept input while still buffering the frame.
    assign s_axis_tready = resetn & filling;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            in_cnt        <= 0;
            emit_cnt      <= 0;
            filling       <= 1'b1;
            emitting      <= 1'b0;
            m_axis_tvalid <= 1'b0;
            m_axis_tdata  <= {DATA_WIDTH{1'b0}};
            m_axis_tlast  <= 1'b0;
            m_axis_tuser  <= 1'b0;
        end else begin
            // ---- FILL: buffer the whole input frame ----
            if (filling && s_axis_tvalid && s_axis_tready) begin
                in_mem[in_cnt] <= s_axis_tdata;
                if (in_cnt == TOTAL_IN-1) begin
                    filling  <= 1'b0;
                    emitting <= 1'b1;
                end
                in_cnt <= in_cnt + 1;
            end

            // ---- EMIT: stream the resized pixels in flat order ----
            if (emitting && (m_axis_tready || !m_axis_tvalid)) begin
                if (emit_cnt < NEEDED) begin
                    src_addr     = (emit_cnt / NX) * SY * IMG_WIDTH_IN
                                 + (emit_cnt % NX) * SX;
                    m_axis_tvalid <= 1'b1;
                    m_axis_tdata  <= in_mem[src_addr];
                    m_axis_tuser  <= (emit_cnt == 0);
                    m_axis_tlast  <= (((emit_cnt + 1) % IMG_WIDTH_OUT) == 0);
                    emit_cnt      <= emit_cnt + 1;
                end else begin
                    m_axis_tvalid <= 1'b0;
                    m_axis_tlast  <= 1'b0;
                    m_axis_tuser  <= 1'b0;
                    emitting      <= 1'b0;
                end
            end
        end
    end
endmodule
"}]}

module enhanced_fsm_signal_processor (
    input  wire        i_clk,        // Clock
    input  wire        i_rst_n,      // Active-low reset
    input  wire        i_enable,     // Start processing
    input  wire        i_clear,      // Clear outputs / fault
    input  wire        i_ack,        // 1-cycle pulse: READY -> IDLE
    input  wire        i_fault,      // Fault condition
    input  wire [4:0]  i_vector_1,
    input  wire [4:0]  i_vector_2,
    input  wire [4:0]  i_vector_3,
    input  wire [4:0]  i_vector_4,
    input  wire [4:0]  i_vector_5,
    input  wire [4:0]  i_vector_6,
    output reg         o_ready,      // Outputs valid / processing complete
    output reg         o_error,      // Fault detected
    output reg  [1:0]  o_fsm_status, // Current FSM state
    output reg  [7:0]  o_vector_1,
    output reg  [7:0]  o_vector_2,
    output reg  [7:0]  o_vector_3,
    output reg  [7:0]  o_vector_4
);

    // FSM state encoding (matches o_fsm_status mapping)
    localparam [1:0] IDLE    = 2'b00,
                     PROCESS = 2'b01,
                     READY   = 2'b10,
                     FAULT   = 2'b11;

    reg [1:0] state, next_state;

    // ---------------------------------------------------------------------
    // All inputs are synchronous to i_clk -> register them before use. This
    // adds the single sampling cycle the FSM timeline relies on.
    // ---------------------------------------------------------------------
    reg        en_r, clr_r, ack_r, flt_r;
    reg [4:0]  v1_r, v2_r, v3_r, v4_r, v5_r, v6_r;

    always @(posedge i_clk or negedge i_rst_n) begin
        if (!i_rst_n) begin
            en_r  <= 1'b0; clr_r <= 1'b0; ack_r <= 1'b0; flt_r <= 1'b0;
            v1_r  <= 5'd0; v2_r <= 5'd0; v3_r <= 5'd0;
            v4_r  <= 5'd0; v5_r <= 5'd0; v6_r <= 5'd0;
        end else begin
            en_r  <= i_enable;
            clr_r <= i_clear;
            ack_r <= i_ack;
            flt_r <= i_fault;
            v1_r  <= i_vector_1; v2_r <= i_vector_2; v3_r <= i_vector_3;
            v4_r  <= i_vector_4; v5_r <= i_vector_5; v6_r <= i_vector_6;
        end
    end

    // Concatenate the six 5-bit vectors (MSB..LSB) into 30 bits, then append
    // two '1' bits at the LSB to form a 32-bit bus.
    wire [31:0] concat_bus = {v1_r, v2_r, v3_r, v4_r, v5_r, v6_r, 2'b11};

    // ---------------------------------------------------------------------
    // Next-state logic uses the registered inputs. i_fault takes precedence
    // over every other input (except clock / reset).
    // ---------------------------------------------------------------------
    always @(*) begin
        next_state = state;
        if (flt_r) begin
            next_state = FAULT;
        end else begin
            case (state)
                IDLE:    next_state = en_r ? PROCESS : IDLE;
                PROCESS: next_state = READY;
                READY:   next_state = ack_r ? IDLE : READY;
                FAULT:   next_state = (clr_r && !flt_r) ? IDLE : FAULT;
                default: next_state = IDLE;
            endcase
        end
    end

    // ---------------------------------------------------------------------
    // Registered state + outputs (all outputs synchronous to i_clk).
    // ---------------------------------------------------------------------
    always @(posedge i_clk or negedge i_rst_n) begin
        if (!i_rst_n) begin
            state        <= IDLE;
            o_ready      <= 1'b0;
            o_error      <= 1'b0;
            o_fsm_status <= IDLE;
            o_vector_1   <= 8'd0;
            o_vector_2   <= 8'd0;
            o_vector_3   <= 8'd0;
            o_vector_4   <= 8'd0;
        end else begin
            state        <= next_state;
            o_fsm_status <= next_state;
            o_ready      <= (next_state == READY);
            o_error      <= (next_state == FAULT);

            // Vector handling: concatenation result is captured while in
            // PROCESS so it becomes valid as the FSM enters READY; outputs are
            // forced to default in IDLE/FAULT.
            if ((state == PROCESS) && !flt_r) begin
                o_vector_1 <= concat_bus[31:24];
                o_vector_2 <= concat_bus[23:16];
                o_vector_3 <= concat_bus[15:8];
                o_vector_4 <= concat_bus[7:0];
            end else if ((next_state == IDLE) || (next_state == FAULT)) begin
                o_vector_1 <= 8'd0;
                o_vector_2 <= 8'd0;
                o_vector_3 <= 8'd0;
                o_vector_4 <= 8'd0;
            end
        end
    end

endmodule

module fan_controller (
    input wire clk, input wire reset, output reg fan_pwm_out,
    input  wire psel, input wire penable, input wire pwrite,
    input  wire [7:0] paddr, input wire [7:0] pwdata,
    output reg  [7:0] prdata, output reg pready, output reg pslverr
);
    reg [7:0] TEMP_LOW, TEMP_MED, TEMP_HIGH, temp_adc_in;
    reg setup;
    wire setup_ph  = psel & ~penable & ~setup;
    wire access_ph = psel &  penable &  setup;
    wire sa=(paddr==8'h0a), sb=(paddr==8'h0b), sc=(paddr==8'h0c), sf=(paddr==8'h0f);
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            prdata<=0; pready<=0; pslverr<=0;
            TEMP_LOW<=8'd30; TEMP_MED<=8'd60; TEMP_HIGH<=8'd90; setup<=0;
        end else begin
            pready <= access_ph; setup <= setup_ph;
            if (access_ph) begin
                pslverr <= ~(sa|sb|sc|sf);
                if (pwrite) begin
                    if (sa) TEMP_LOW<=pwdata; if (sb) TEMP_MED<=pwdata;
                    if (sc) TEMP_HIGH<=pwdata; if (sf) temp_adc_in<=pwdata;
                end else
                    prdata <= sa?TEMP_LOW : sb?TEMP_MED : sc?TEMP_HIGH : sf?temp_adc_in : prdata;
            end
        end
    end
    reg [7:0] pwm_duty_cycle, pwm_counter;
    always @(posedge clk or posedge reset)
        if (reset) pwm_duty_cycle<=0;
        else pwm_duty_cycle <= (temp_adc_in<TEMP_LOW)?8'd64:(temp_adc_in<TEMP_MED)?8'd128:(temp_adc_in<TEMP_HIGH)?8'd11:8'd255;
    always @(posedge clk or posedge reset)
        if (reset) begin pwm_counter<=0; fan_pwm_out<=0; end
        else begin pwm_counter<=pwm_counter+1; fan_pwm_out<=(pwm_counter<pwm_duty_cycle); end
endmodule

module hill_cipher (
    input  logic        clk,
    input  logic        reset,
    input  logic        start,
    input  logic [14:0] plaintext,   // 3 letters, 5 bits each
    input  logic [44:0] key,         // 9 elements, 5 bits each
    output logic [14:0] ciphertext,  // 3 letters, 5 bits each
    output logic        done
);

    logic [4:0] P0, P1, P2;
    logic [4:0] K00, K01, K02;
    logic [4:0] K10, K11, K12;
    logic [4:0] K20, K21, K22;

    // Each product K*P <= 31*31 = 961 (10 bits); the sum of three products is
    // <= 2883 (12 bits). 12-bit accumulators avoid any intermediate truncation.
    logic [11:0] temp0, temp1, temp2;
    // Modulo-26 results are 0..25 (5 bits). The explicit 5-bit cast makes the
    // narrowing intentional (no truncation warning) and leaves no unused bits.
    logic [4:0] c0_mod, c1_mod, c2_mod;

    typedef enum logic [1:0] {
        IDLE        = 2'b00,
        COMPUTE     = 2'b01,
        COMPUTE_MOD = 2'b10,
        DONE        = 2'b11
    } state_t;

    state_t current_state, next_state;

    assign P0 = plaintext[14:10];
    assign P1 = plaintext[9:5];
    assign P2 = plaintext[4:0];

    assign K00 = key[44:40];
    assign K01 = key[39:35];
    assign K02 = key[34:30];
    assign K10 = key[29:25];
    assign K11 = key[24:20];
    assign K12 = key[19:15];
    assign K20 = key[14:10];
    assign K21 = key[9:5];
    assign K22 = key[4:0];

    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    always_comb begin
        next_state = current_state;
        done       = 1'b0;
        case (current_state)
            IDLE:        if (start) next_state = COMPUTE;
            COMPUTE:     next_state = COMPUTE_MOD;
            COMPUTE_MOD: next_state = DONE;
            DONE: begin
                done       = 1'b1;
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            temp0  <= 12'b0;
            temp1  <= 12'b0;
            temp2  <= 12'b0;
            c0_mod <= 5'b0;
            c1_mod <= 5'b0;
            c2_mod <= 5'b0;
        end
        else begin
            case (current_state)
                COMPUTE: begin
                    temp0 <= (12'(K00) * 12'(P0)) + (12'(K01) * 12'(P1)) + (12'(K02) * 12'(P2));
                    temp1 <= (12'(K10) * 12'(P0)) + (12'(K11) * 12'(P1)) + (12'(K12) * 12'(P2));
                    temp2 <= (12'(K20) * 12'(P0)) + (12'(K21) * 12'(P1)) + (12'(K22) * 12'(P2));
                end
                COMPUTE_MOD: begin
                    c0_mod <= 5'(temp0 % 12'd26);
                    c1_mod <= 5'(temp1 % 12'd26);
                    c2_mod <= 5'(temp2 % 12'd26);
                end
                default: begin
                    temp0  <= 12'b0;
                    temp1  <= 12'b0;
                    temp2  <= 12'b0;
                    c0_mod <= 5'b0;
                    c1_mod <= 5'b0;
                    c2_mod <= 5'b0;
                end
            endcase
        end
    end

    assign ciphertext = { c0_mod, c1_mod, c2_mod };

endmodule

module cvdp_copilot_register_file_2R1W #(
    parameter DATA_WIDTH = 32,  // Configurable data width
    parameter DEPTH      = 32   // Number of register entries
) (
    // Inputs
    input  logic [DATA_WIDTH-1:0] din,    // Input data
    input  logic [4:0] wad1,              // Write address
    input  logic [4:0] rad1,              // Read address 1
    input  logic [4:0] rad2,              // Read address 2
    input  logic wen1,                    // Write-enable signal
    input  logic ren1,                    // Read-enable signal 1
    input  logic ren2,                    // Read-enable signal 2
    input  logic clk,                     // Clock signal
    input  logic resetn,                  // Active-low reset
    input  logic test_mode,               // BIST activation (active high)

    // Outputs
    output logic [DATA_WIDTH-1:0] dout1,   // Output data 1
    output logic [DATA_WIDTH-1:0] dout2,   // Output data 2
    output logic collision,                // Collision flag
    output logic bist_done,                // BIST sequence complete
    output logic bist_fail                 // BIST detected a mismatch
);

    localparam ADDRW = 5;  // address width for up to 32 entries

    // -------------------------------
    // Internal Registers and Wires
    // -------------------------------
    logic [DATA_WIDTH-1:0] rf_mem [0:DEPTH-1];
    logic [DEPTH-1:0]      rf_valid;       // Validity of each register entry
    integer i;

    // -------------------------------
    // BIST control
    // -------------------------------
    localparam [1:0] BIST_IDLE  = 2'b00,
                     BIST_WRITE = 2'b01,
                     BIST_READ  = 2'b10,
                     BIST_DONE  = 2'b11;

    logic [1:0]       bist_state;
    logic [ADDRW:0]   bist_addr;     // 0..DEPTH (extra bit for the terminal count)

    // Deterministic march pattern: each location's expected data is its address.
    function automatic logic [DATA_WIDTH-1:0] pat(input logic [ADDRW-1:0] a);
        pat = { {(DATA_WIDTH-ADDRW){1'b0}}, a };
    endfunction

    // NOTE on clocking: every flop in this design is clocked by the primary `clk`.
    // The original starter RTL gated the write clock through an enable latch, which
    // made the gated clock lag `clk` by a delta cycle; a single-cycle `wen1` pulse
    // driven off `clk` then raced that lagged edge and was dropped. Using the
    // ungated `clk` for the synchronous write makes single-cycle writes reliable
    // and keeps the write path aligned with the BIST FSM (also on `clk`).

    // -------------------------------
    // Register File Memory (single driver): BIST write during test_mode,
    // otherwise the normal write port. Normal writes are disabled in test_mode.
    // -------------------------------
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            for (i = 0; i < DEPTH; i = i + 1) begin
                rf_mem[i] <= {DATA_WIDTH{1'b0}};
            end
            rf_valid <= {DEPTH{1'b0}};
        end
        else if (test_mode) begin
            if (bist_state == BIST_WRITE) begin
                rf_mem[bist_addr[ADDRW-1:0]]   <= pat(bist_addr[ADDRW-1:0]);
                rf_valid[bist_addr[ADDRW-1:0]] <= 1'b1;
            end
        end
        else if (wen1) begin
            rf_mem[wad1]    <= din;  // Write operation
            rf_valid[wad1]  <= 1'b1; // Mark written address as valid
        end
    end

    // -------------------------------
    // BIST FSM + compare (plain clock)
    // -------------------------------
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            bist_state <= BIST_IDLE;
            bist_addr  <= '0;
            bist_done  <= 1'b0;
            bist_fail  <= 1'b0;
        end
        else if (test_mode) begin
            case (bist_state)
                BIST_IDLE: begin
                    bist_state <= BIST_WRITE;
                    bist_addr  <= '0;
                    bist_done  <= 1'b0;
                    bist_fail  <= 1'b0;
                end
                BIST_WRITE: begin
                    if (bist_addr == (DEPTH-1)) begin
                        bist_addr  <= '0;
                        bist_state <= BIST_READ;
                    end else begin
                        bist_addr <= bist_addr + 1'b1;
                    end
                end
                BIST_READ: begin
                    if (rf_mem[bist_addr[ADDRW-1:0]] != pat(bist_addr[ADDRW-1:0]))
                        bist_fail <= 1'b1;
                    if (bist_addr == (DEPTH-1)) begin
                        bist_state <= BIST_DONE;
                    end else begin
                        bist_addr <= bist_addr + 1'b1;
                    end
                end
                BIST_DONE: begin
                    bist_done <= 1'b1;
                end
                default: bist_state <= BIST_IDLE;
            endcase
        end
        else begin
            bist_state <= BIST_IDLE;
            bist_done  <= 1'b0;
            bist_fail  <= 1'b0;
        end
    end

    // -------------------------------
    // Read Data Output Logic for Port 1 (COMBINATIONAL read).
    // A 2R1W register file uses zero-latency read ports: a value written on a prior
    // edge is visible the moment ren1+rad1 are presented, with no extra
    // registered-read delay. Disabled in test_mode (normal ops off during BIST).
    // -------------------------------
    always_comb begin
        if (!test_mode && ren1)
            dout1 = rf_valid[rad1] ? rf_mem[rad1] : '0;
        else
            dout1 = '0;
    end

    // -------------------------------
    // Read Data Output Logic for Port 2 (COMBINATIONAL read).
    // -------------------------------
    always_comb begin
        if (!test_mode && ren2)
            dout2 = rf_valid[rad2] ? rf_mem[rad2] : '0;
        else
            dout2 = '0;
    end

    // -------------------------------
    // Collision Detection Logic with Original Clock (disabled in test_mode)
    // -------------------------------
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            collision <= 1'b0;
        end
        else if (test_mode) begin
            collision <= 1'b0;
        end
        else begin
            collision <= (
                (ren1 && ren2 && (rad1 == rad2)) ||          // Both reads to the same address
                (wen1 && ren1 && (wad1 == rad1)) ||          // Write and read to the same address
                (wen1 && ren2 && (wad1 == rad2))             // Write and read to the same address
            );
        end
    end

endmodule

module sigma_delta_audio
(
  input   clk_sig,
  input   clk_en_sig,
  input  [14:0] load_data_sum,
  input  [14:0] read_data_sum,
  output  reg left_sig=0,
  output  reg right_sig=0
);

localparam DATA_WIDTH = 15;
localparam READ_WIDTH  = 4;
localparam A1_WIDTH = 2;
localparam A2_WIDTH = 5;

wire [DATA_WIDTH+2+0  -1:0] l_er0, r_er0;
reg  [DATA_WIDTH+2+0  -1:0] l_er0_prev=0, r_er0_prev=0;
wire [DATA_WIDTH+A1_WIDTH+2-1:0] l_aca1,  r_aca1;
wire [DATA_WIDTH+A2_WIDTH+2-1:0] l_aca2,  r_aca2;
reg  [DATA_WIDTH+A1_WIDTH+2-1:0] l_ac1=0, r_ac1=0;
reg  [DATA_WIDTH+A2_WIDTH+2-1:0] l_ac2=0, r_ac2=0;
wire [DATA_WIDTH+A2_WIDTH+3-1:0] l_quant, r_quant;

reg [24-1:0] seed_1 = 24'h654321;
reg [19-1:0] seed_2 = 19'h12345;
reg [24-1:0] s_sum=0, s_prev=0, s_out=0;
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    if (&seed_1)
      seed_1 <= 24'h654321;
    else
      seed_1 <= {seed_1[22:0], ~(seed_1[23] ^ seed_1[22] ^ seed_1[21] ^ seed_1[16])};
  end
end
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    if (&seed_2)
      seed_2 <= 19'h12345;
    else
      seed_2 <= {seed_2[17:0], ~(seed_2[18] ^ seed_2[17] ^ seed_2[16] ^ seed_2[13] ^ seed_2[0])};
  end
end
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    s_sum  <= seed_1 + {5'b0, seed_2};
    s_prev <= s_sum;
    s_out  <= s_sum - s_prev;
  end
end

localparam INPUT_DATA=4;
reg  [INPUT_DATA+0-1:0] integer_count = 0;
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    integer_count <= integer_count + 'd1;
  end
end

reg  [DATA_WIDTH+0-1:0] ldata_current=0, ldata_previous=0;
reg  [DATA_WIDTH+0-1:0] rdata_current=0, rdata_previous=0;
wire [DATA_WIDTH+1-1:0] load_data_step, read_data_step;
reg  [DATA_WIDTH+INPUT_DATA-1:0] load_data_int=0, read_data_int=0;
wire [DATA_WIDTH+0-1:0] load_data_int_out, read_data_int_out;
assign load_data_step = {ldata_current[DATA_WIDTH-1], ldata_current} - {ldata_previous[DATA_WIDTH-1], ldata_previous};
assign read_data_step = {rdata_current[DATA_WIDTH-1], rdata_current} - {rdata_previous[DATA_WIDTH-1], rdata_previous};
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    if (~|integer_count) begin
      ldata_previous <= ldata_current;
      ldata_current  <= load_data_sum;
      rdata_previous <= rdata_current;
      rdata_current  <= read_data_sum;
      load_data_int  <= {ldata_current, {INPUT_DATA{1'b0}}};
      read_data_int  <= {rdata_current, {INPUT_DATA{1'b0}}};
    end else begin
      load_data_int  <= load_data_int + {{(INPUT_DATA-1){load_data_step[DATA_WIDTH+1-1]}}, load_data_step};
      read_data_int  <= read_data_int + {{(INPUT_DATA-1){read_data_step[DATA_WIDTH+1-1]}}, read_data_step};
    end
  end
end
assign load_data_int_out = load_data_int[DATA_WIDTH+INPUT_DATA-1:INPUT_DATA];
assign read_data_int_out = read_data_int[DATA_WIDTH+INPUT_DATA-1:INPUT_DATA];

wire [DATA_WIDTH+2-1:0] load_data_gain, read_data_gain;
assign load_data_gain = {load_data_int_out[DATA_WIDTH-1], load_data_int_out, 1'b0} + {{(2){load_data_int_out[DATA_WIDTH-1]}}, load_data_int_out};
assign read_data_gain = {read_data_int_out[DATA_WIDTH-1], read_data_int_out, 1'b0} + {{(2){read_data_int_out[DATA_WIDTH-1]}}, read_data_int_out};

assign l_aca1 = {{(A1_WIDTH){load_data_gain[DATA_WIDTH+2-1]}}, load_data_gain} - {{(A1_WIDTH){l_er0[DATA_WIDTH+2-1]}}, l_er0} + l_ac1;
assign r_aca1 = {{(A1_WIDTH){read_data_gain[DATA_WIDTH+2-1]}}, read_data_gain} - {{(A1_WIDTH){r_er0[DATA_WIDTH+2-1]}}, r_er0} + r_ac1;
assign l_aca2 = {{(A2_WIDTH-A1_WIDTH){l_aca1[DATA_WIDTH+A1_WIDTH+2-1]}}, l_aca1} - {{(A2_WIDTH){l_er0[DATA_WIDTH+2-1]}}, l_er0} - {{(A2_WIDTH+1){l_er0_prev[DATA_WIDTH+2-1]}}, l_er0_prev[DATA_WIDTH+2-1:1]} + l_ac2;
assign r_aca2 = {{(A2_WIDTH-A1_WIDTH){r_aca1[DATA_WIDTH+A1_WIDTH+2-1]}}, r_aca1} - {{(A2_WIDTH){r_er0[DATA_WIDTH+2-1]}}, r_er0} - {{(A2_WIDTH+1){r_er0_prev[DATA_WIDTH+2-1]}}, r_er0_prev[DATA_WIDTH+2-1:1]} + r_ac2;

always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    l_ac1 <= l_aca1;
    r_ac1 <= r_aca1;
    l_ac2 <= l_aca2;
    r_ac2 <= r_aca2;
  end
end

assign l_quant = {l_ac2[DATA_WIDTH+A2_WIDTH+2-1], l_ac2} + {{(DATA_WIDTH+A2_WIDTH+3-READ_WIDTH){s_out[READ_WIDTH-1]}}, s_out[READ_WIDTH-1:0]};
assign r_quant = {r_ac2[DATA_WIDTH+A2_WIDTH+2-1], r_ac2} + {{(DATA_WIDTH+A2_WIDTH+3-READ_WIDTH){s_out[READ_WIDTH-1]}}, s_out[READ_WIDTH-1:0]};

assign l_er0 = l_quant[DATA_WIDTH+A2_WIDTH+3-1] ? {1'b1, {(DATA_WIDTH+2-1){1'b0}}} : {1'b0, {(DATA_WIDTH+2-1){1'b1}}};
assign r_er0 = r_quant[DATA_WIDTH+A2_WIDTH+3-1] ? {1'b1, {(DATA_WIDTH+2-1){1'b0}}} : {1'b0, {(DATA_WIDTH+2-1){1'b1}}};

always @ (posedge clk_sig)
begin
  if (clk_en_sig)
  begin
    if (~|load_data_gain)
    begin
      left_sig <= ~left_sig;
    end
    else
    begin
      left_sig <= ~l_er0[DATA_WIDTH+2-1];
    end

    if (~|read_data_gain)
    begin
      right_sig <= ~right_sig;
    end
    else
    begin
      right_sig <= ~r_er0[DATA_WIDTH+2-1];
    end
  end
end
endmodule

// Synchronous serial communication link.
//   Top      : sync_serial_communication_tx_rx (instantiates tx_block + rx_block)
//   tx_block : serialises data_in[N-1:0] (N selected by sel) onto serial_out, one
//              bit per clock, LSB-first, and emits serial_clk active only while a
//              serial bit is valid (gated when idle).
//   rx_block : captures serial_out while serial_clk is active and reconstructs the
//              parallel data_out, asserting done HIGH for one clock when complete.
//
//   sel : 1->8 | 2->16 | 3->32 | 4->64 | other->0 bits (idle, no transfer)
//
// Whole design is in a single clock domain (all signals registered on clk) so
// there are no gated-clock sampling races; serial_clk is an active-high transfer
// strobe (gated off when no data is being transmitted).

// ---------------------------------------------------------------------------
module tx_block (
    input  logic        clk,
    input  logic        reset_n,     // active-low asynchronous reset
    input  logic [63:0] data_in,
    input  logic [2:0]  sel,
    output logic        serial_out,
    output logic        done,
    output logic        serial_clk
);
    logic [6:0] n_bits;
    always_comb begin
        case (sel)
            3'd1:    n_bits = 7'd8;
            3'd2:    n_bits = 7'd16;
            3'd3:    n_bits = 7'd32;
            3'd4:    n_bits = 7'd64;
            default: n_bits = 7'd0;
        endcase
    end

    logic [63:0] shiftreg;
    logic [6:0]  count;
    logic        busy;
    logic        started;
    logic        active;     // high while a valid serial bit is on serial_out

    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            shiftreg   <= 64'd0;
            count      <= 7'd0;
            busy       <= 1'b0;
            started    <= 1'b0;
            active     <= 1'b0;
            serial_out <= 1'b0;
            done       <= 1'b0;
        end else begin
            done   <= 1'b0;
            active <= 1'b0;
            if (!busy && !started && (n_bits != 7'd0)) begin
                // launch one transaction after reset is released
                shiftreg <= data_in;
                count    <= 7'd0;
                busy     <= 1'b1;
                started  <= 1'b1;
            end else if (busy) begin
                // emit one bit per clock, LSB first
                serial_out <= shiftreg[count[5:0]];
                active     <= 1'b1;
                count      <= count + 7'd1;
                if (count == n_bits - 7'd1) begin
                    busy <= 1'b0;
                    done <= 1'b1;   // tx-side completion (rx.done is the system done)
                end
            end
        end
    end

    // serial_clk is gated: active only while a serial bit is being transmitted.
    assign serial_clk = active;
endmodule

// ---------------------------------------------------------------------------
module rx_block (
    input  logic        clk,
    input  logic        reset_n,     // active-low asynchronous reset
    input  logic        data_in,     // serial input
    input  logic [2:0]  sel,
    input  logic        serial_clk,  // active-high transfer strobe
    output logic [63:0] data_out,
    output logic        done
);
    logic [6:0] n_bits;
    always_comb begin
        case (sel)
            3'd1:    n_bits = 7'd8;
            3'd2:    n_bits = 7'd16;
            3'd3:    n_bits = 7'd32;
            3'd4:    n_bits = 7'd64;
            default: n_bits = 7'd0;
        endcase
    end

    logic [63:0] rx_data;
    logic [6:0]  rx_count;
    logic        last_bit;

    always_ff @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            rx_data  <= 64'd0;
            rx_count <= 7'd0;
            last_bit <= 1'b0;
            data_out <= 64'd0;
            done     <= 1'b0;
        end else begin
            done     <= 1'b0;
            last_bit <= 1'b0;
            if (serial_clk) begin
                rx_data[rx_count[5:0]] <= data_in;   // LSB-first placement
                if (rx_count == n_bits - 7'd1)
                    last_bit <= 1'b1;                 // last bit captured this cycle
                rx_count <= rx_count + 7'd1;
            end
            if (last_bit) begin
                // one cycle later rx_data holds the complete word
                data_out <= rx_data;
                done     <= 1'b1;
            end
        end
    end
endmodule

// ---------------------------------------------------------------------------
module sync_serial_communication_tx_rx (
    input  logic        clk,
    input  logic        reset_n,
    input  logic [63:0] data_in,
    input  logic [2:0]  sel,
    output logic [63:0] data_out,
    output logic        done
);
    logic s_serial_out;
    logic s_serial_clk;
    logic s_tx_done;

    tx_block u_tx (
        .clk        (clk),
        .reset_n    (reset_n),
        .data_in    (data_in),
        .sel        (sel),
        .serial_out (s_serial_out),
        .done       (s_tx_done),
        .serial_clk (s_serial_clk)
    );

    rx_block u_rx (
        .clk        (clk),
        .reset_n    (reset_n),
        .data_in    (s_serial_out),
        .sel        (sel),
        .serial_clk (s_serial_clk),
        .data_out   (data_out),
        .done       (done)
    );
endmodule

module apb_dsp_unit (
    input  wire        pclk,        // APB clock
    input  wire        presetn,     // active-low async reset
    input  wire [9:0]  paddr,       // address bus
    input  wire        pselx,       // select
    input  wire        penable,     // enable
    input  wire        pwrite,      // 1 = write, 0 = read
    input  wire [7:0]  pwdata,      // write data
    input  wire        sram_valid,  // posedge latches r_write_data -> SRAM
    output reg         pready,      // transfer ready
    output reg [7:0]   prdata,      // read data
    output reg         pslverr      // error response
);

    // ---- Configuration registers ----
    reg [7:0] r_operand_1;      // 0x0 : address of operand 1
    reg [7:0] r_operand_2;      // 0x1 : address of operand 2
    reg [7:0] r_Enable;         // 0x2 : 0=off 1=add 2=mul 3=write
    reg [7:0] r_write_address;  // 0x3 : memory write address
    reg [7:0] r_write_data;     // 0x4 : memory write data
    // 0x5 : computed result (read-only, see dsp_result)

    // ---- 1 KB SRAM ----
    reg [7:0] sram [0:1023];

    // ---- DSP combinational result ----
    reg [15:0] dsp_result;
    always @(*) begin
        case (r_Enable)
            8'd1:    dsp_result = sram[r_operand_1] + sram[r_operand_2]; // addition
            8'd2:    dsp_result = sram[r_operand_1] * sram[r_operand_2]; // multiplication
            default: dsp_result = 16'd0;
        endcase
    end

    // ---- SRAM write on the rising edge of sram_valid (write mode) ----
    // Spec: "At positive edge of this signal, data in r_write_data is latched
    //        to address in r_write_address" (when r_Enable == write mode).
    always @(posedge sram_valid) begin
        if (r_Enable == 8'd3)
            sram[r_write_address] <= r_write_data;
    end

    // ---- APB slave (no wait states: PREADY always high) ----
    always @(posedge pclk or negedge presetn) begin
        if (!presetn) begin
            pready          <= 1'b0;
            prdata          <= 8'd0;
            pslverr         <= 1'b0;
            r_operand_1     <= 8'd0;
            r_operand_2     <= 8'd0;
            r_Enable        <= 8'd0;
            r_write_address <= 8'd0;
            r_write_data    <= 8'd0;
        end else begin
            pready  <= 1'b1;
            pslverr <= 1'b0;
            if (pselx && penable) begin
                if (pwrite) begin
                    case (paddr)
                        10'h0:   r_operand_1     <= pwdata;
                        10'h1:   r_operand_2     <= pwdata;
                        10'h2:   r_Enable        <= pwdata;
                        10'h3:   r_write_address <= pwdata;
                        10'h4:   r_write_data    <= pwdata;
                        default: pslverr         <= 1'b1; // write to unmapped CSR addr
                    endcase
                end else begin
                    case (paddr)
                        10'h0:   prdata <= r_operand_1;
                        10'h1:   prdata <= r_operand_2;
                        10'h2:   prdata <= r_Enable;
                        10'h3:   prdata <= r_write_address;
                        10'h4:   prdata <= r_write_data;
                        10'h5:   prdata <= dsp_result[7:0];  // computed result
                        default: prdata <= sram[paddr];      // memory read-back
                    endcase
                end
            end
        end
    end

endmodule

module binary_search_tree_sort #(
    parameter DATA_WIDTH = 32,
    parameter ARRAY_SIZE = 8
) (
    input clk,
    input reset,
    input reg [ARRAY_SIZE*DATA_WIDTH-1:0] data_in, // Input data to be sorted
    input start,
    output reg [ARRAY_SIZE*DATA_WIDTH-1:0] sorted_out, // Sorted output
    output reg done
);

    // Parameters for top-level FSM states
    parameter IDLE = 2'b00, BUILD_TREE = 2'b01, SORT_TREE = 2'b10;

    // Sub-FSM state encodings (BUILD_TREE)
    localparam INIT     = 2'd0,  // load next number / detect completion
               LOAD     = 2'd1,  // root insertion or start of traversal
               TRAVERSE = 2'd2,  // descend tree to find insertion point
               COMPLETE = 2'd3;  // build finished

    // Sub-FSM state encodings (SORT_TREE) -- in-order traversal.
    // The pop phase is split so that each visited node costs exactly three
    // cycles (store output / assign right child / check right child), which is
    // what the spec's SORT_TREE latency (4*ARRAY_SIZE + 3) requires.
    localparam S_INIT  = 3'd0,   // assign root to current_node
               S_LEFT  = 3'd1,   // push and walk left (also empty-stack done)
               S_POP   = 3'd2,   // pop + store output
               S_RIGHT = 3'd3,   // assign right child of popped node
               S_DONE  = 3'd4;   // traversal finished

    // Pointer width and null encoding
    localparam PW = $clog2(ARRAY_SIZE) + 1;
    localparam [PW-1:0] NULLP = {PW{1'b1}};

    // Registers for FSM states
    reg [1:0] top_state, build_state;
    reg [2:0] sort_state;        // widened: SORT_TREE has five states

    // BST representation
    reg [ARRAY_SIZE*DATA_WIDTH-1:0] keys; // Array to store node keys
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] left_child; // Left child pointers
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] right_child; // Right child pointers
    reg [$clog2(ARRAY_SIZE):0] root; // Root node pointer
    reg [$clog2(ARRAY_SIZE):0] next_free_node; // Pointer to the next free node

    // Stack for in-order traversal
    reg [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] stack; // Stack for traversal
    reg [$clog2(ARRAY_SIZE):0] sp; // Stack pointer

    // Working registers
    reg [$clog2(ARRAY_SIZE):0] current_node; // Current node being processed
    reg [$clog2(ARRAY_SIZE):0] input_index; // Index for input data
    reg [$clog2(ARRAY_SIZE):0] output_index; // Index for output data
    reg [DATA_WIDTH-1:0] temp_data; // Temporary data register
    reg [PW-1:0] popped_node; // Node id popped from the stack (for right-child step)

    // Latched input array (ignore changes on data_in during operation)
    reg [ARRAY_SIZE*DATA_WIDTH-1:0] data_latched;

    // Combinational read of the top-of-stack node id
    wire [PW-1:0] sp_top = (sp != 0) ? stack[(sp-1)*PW +: PW] : NULLP;

    // Initialize all variables
    integer i;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset all states and variables
            top_state <= IDLE;
            build_state <= INIT;
            sort_state <= S_INIT;

            root <= {($clog2(ARRAY_SIZE)+1){1'b1}}; // Null pointer
            next_free_node <= 0;
            sp <= 0;
            input_index <= 0;
            output_index <= 0;
            popped_node <= NULLP;
            done <= 0;
            sorted_out <= {(ARRAY_SIZE*DATA_WIDTH){1'b0}};

            // Clear tree arrays
            for (i = 0; i < ARRAY_SIZE; i = i + 1) begin
                keys[i*DATA_WIDTH +: DATA_WIDTH] <= 0;
                left_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                right_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
            end

        end else begin
            case (top_state)
                IDLE: begin
                    done <= 0;
                    sorted_out <= {(ARRAY_SIZE*DATA_WIDTH){1'b0}};
                    input_index <= 0;
                    output_index <= 0;
                    root <= {($clog2(ARRAY_SIZE)+1){1'b1}}; // Null pointer
                    next_free_node <= 0;
                    sp <= 0;
                    for (i = 0; i < ARRAY_SIZE+1; i = i + 1) begin
                        keys[i*DATA_WIDTH +: DATA_WIDTH] <= 0;
                        left_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        right_child[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                        stack[i*($clog2(ARRAY_SIZE)+1) +: ($clog2(ARRAY_SIZE)+1)] <= {($clog2(ARRAY_SIZE)+1){1'b1}};
                    end
                    if (start) begin
                        // Load input data into input array
                        data_latched <= data_in;
                        top_state <= BUILD_TREE;
                        build_state <= INIT;
                    end
                end

                BUILD_TREE: begin
                    case (build_state)

                        INIT: begin
                            if (input_index >= ARRAY_SIZE) begin
                                build_state <= COMPLETE;
                            end else begin
                                temp_data   <= data_latched[input_index*DATA_WIDTH +: DATA_WIDTH];
                                build_state <= LOAD;
                            end
                        end

                        LOAD: begin
                            if (root == NULLP) begin
                                // Empty tree: insert the root node
                                keys[next_free_node*DATA_WIDTH +: DATA_WIDTH] <= temp_data;
                                root           <= next_free_node;
                                next_free_node <= next_free_node + 1'b1;
                                input_index    <= input_index + 1'b1;
                                build_state    <= INIT;
                            end else begin
                                current_node <= root;
                                build_state  <= TRAVERSE;
                            end
                        end

                        TRAVERSE: begin
                            if (temp_data > keys[current_node*DATA_WIDTH +: DATA_WIDTH]) begin
                                // Go right
                                if (right_child[current_node*PW +: PW] == NULLP) begin
                                    right_child[current_node*PW +: PW] <= next_free_node;
                                    keys[next_free_node*DATA_WIDTH +: DATA_WIDTH] <= temp_data;
                                    next_free_node <= next_free_node + 1'b1;
                                    input_index    <= input_index + 1'b1;
                                    build_state    <= INIT;
                                end else begin
                                    current_node <= right_child[current_node*PW +: PW];
                                end
                            end else begin
                                // Go left
                                if (left_child[current_node*PW +: PW] == NULLP) begin
                                    left_child[current_node*PW +: PW] <= next_free_node;
                                    keys[next_free_node*DATA_WIDTH +: DATA_WIDTH] <= temp_data;
                                    next_free_node <= next_free_node + 1'b1;
                                    input_index    <= input_index + 1'b1;
                                    build_state    <= INIT;
                                end else begin
                                    current_node <= left_child[current_node*PW +: PW];
                                end
                            end
                        end

                        COMPLETE: begin
                            // Tree construction complete
                            top_state <= SORT_TREE;
                            sort_state <= S_INIT;
                        end

                    endcase
                end

                SORT_TREE: begin
                    case (sort_state)

                        S_INIT: begin
                            // Assign root to current_node (1 cycle)
                            current_node <= root;
                            sort_state   <= S_LEFT;
                        end

                        S_LEFT: begin
                            if (current_node != NULLP) begin
                                // Push current node and descend left
                                stack[sp*PW +: PW] <= current_node;
                                sp           <= sp + 1'b1;
                                current_node <= left_child[current_node*PW +: PW];
                            end else if (sp == 0) begin
                                // Stack empty and no current node -> traversal done.
                                // Folding the empty-stack check in here keeps the
                                // per-node pop cost at exactly three cycles.
                                sort_state <= S_DONE;
                            end else begin
                                sort_state <= S_POP;
                            end
                        end

                        S_POP: begin
                            // Store output (pop the top-of-stack node, emit its key)
                            sorted_out[output_index*DATA_WIDTH +: DATA_WIDTH] <= keys[sp_top*DATA_WIDTH +: DATA_WIDTH];
                            output_index <= output_index + 1'b1;
                            popped_node  <= sp_top;
                            sp           <= sp - 1'b1;
                            sort_state   <= S_RIGHT;
                        end

                        S_RIGHT: begin
                            // Assign right child of the popped node, then go back
                            // to S_LEFT which checks whether it exists.
                            current_node <= right_child[popped_node*PW +: PW];
                            sort_state   <= S_LEFT;
                        end

                        S_DONE: begin
                            done      <= 1'b1;
                            top_state <= IDLE;
                        end

                    endcase
                end
            endcase
        end
    end
endmodule

// advanced_decimator_with_adaptive_peak_detection
//
// Decimation + signed peak detection.
//
// Behaviour (matched to the shipped cocotb reference model):
//   - Input samples are packed into data_in with sample slot s occupying
//     bits [DATA_WIDTH*s +: DATA_WIDTH] (slot 0 == LSB).
//   - Decimation selects one slot for every DEC_FACTOR slots:
//         data_out slot q = data_in slot (q * DEC_FACTOR),  q = 0 .. M-1
//     where M = N / DEC_FACTOR.
//   - peak_value = signed maximum across the M decimated slots.
//   - Latency is exactly 1 clock cycle: the input bus and valid are
//     registered on the rising edge (async active-high reset clears them);
//     decimation, peak detection and output packing are combinational from
//     the registered data.

module advanced_decimator_with_adaptive_peak_detection #(
    parameter int N          = 8,
    parameter int DATA_WIDTH = 16,
    parameter int DEC_FACTOR = 4
) (
    input  wire                                       clk,
    input  wire                                       reset,
    input  wire                                       valid_in,
    input  wire [DATA_WIDTH*N-1:0]                    data_in,
    output reg                                        valid_out,
    output wire [DATA_WIDTH*(N/DEC_FACTOR)-1:0]       data_out,
    output wire [DATA_WIDTH-1:0]                       peak_value
);

    localparam int M = N / DEC_FACTOR;

    // ------------------------------------------------------------------
    // 1. Input registering + validation control (sequential, async reset)
    // ------------------------------------------------------------------
    reg [DATA_WIDTH*N-1:0] data_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            data_reg  <= '0;
            valid_out <= 1'b0;
        end else begin
            data_reg  <= data_in;
            valid_out <= valid_in;
        end
    end

    // ------------------------------------------------------------------
    // 2. Decimation + output packing (combinational from registered data)
    //    data_out slot q = data_reg slot (q * DEC_FACTOR)
    // ------------------------------------------------------------------
    genvar q;
    generate
        for (q = 0; q < M; q = q + 1) begin : gen_decimate
            assign data_out[DATA_WIDTH*q +: DATA_WIDTH] =
                   data_reg[DATA_WIDTH*(q*DEC_FACTOR) +: DATA_WIDTH];
        end
    endgenerate

    // ------------------------------------------------------------------
    // 3. Peak detection (signed maximum across decimated samples)
    // ------------------------------------------------------------------
    reg signed [DATA_WIDTH-1:0] peak_comb;
    integer k;
    always @(*) begin
        peak_comb = $signed(data_out[DATA_WIDTH-1:0]); // slot 0
        for (k = 1; k < M; k = k + 1) begin
            if ($signed(data_out[DATA_WIDTH*k +: DATA_WIDTH]) > peak_comb)
                peak_comb = $signed(data_out[DATA_WIDTH*k +: DATA_WIDTH]);
        end
    end

    assign peak_value = peak_comb;

endmodule

// sgd_linear_regression
// Stochastic Gradient Descent (SGD) linear-regression trainer.
//
// Literal spec implementation:
//   * y_pred / error / delta_w / delta_b are pure combinational logic of the
//     current weight/bias registers and the current inputs.
//   * w / b are sequential: on each rising edge (when not in reset)
//       w <= trunc(w + delta_w);  b <= trunc(b + delta_b)
//     where the sum is truncated to DATA_WIDTH (its low bits), matching the
//     reference model's apply_bit_limit().
//
// The cocotb test reads dut.w_out / dut.b_out, so the output ports are named
// w_out / b_out.
module sgd_linear_regression #(
    parameter DATA_WIDTH    = 16,
    parameter LEARNING_RATE = 3'd1
) (
    input  logic                          clk,      // Clock
    input  logic                          reset,    // Asynchronous reset (active high)
    input  logic signed [DATA_WIDTH-1:0]  x_in,     // Input data (x)
    input  logic signed [DATA_WIDTH-1:0]  y_true,   // True output (target)
    output logic signed [DATA_WIDTH-1:0]  w_out,    // Trained weight
    output logic signed [DATA_WIDTH-1:0]  b_out     // Trained bias
);

    localparam NBW_PRED  = 2*DATA_WIDTH + 1;
    localparam NBW_ERROR = NBW_PRED + 1;
    localparam NBW_DELTA = 3 + NBW_ERROR + DATA_WIDTH;

    // Signed learning-rate constant (allowed values 0/1/2 -> always positive).
    // Explicitly signed so the delta multiplications are signed.
    localparam signed [3:0] LR_S = LEARNING_RATE;

    // Weight / bias registers
    logic signed [DATA_WIDTH-1:0] w_reg, b_reg;

    // Combinational intermediates
    logic signed [NBW_PRED-1:0]  y_pred;
    logic signed [NBW_ERROR-1:0] error;
    logic signed [NBW_DELTA-1:0] delta_w;
    logic signed [NBW_DELTA-1:0] delta_b;

    // Predicted output: y_pred = w*x_in + b
    always_comb begin
        y_pred = (w_reg * x_in) + b_reg;
    end

    // Error: error = y_true - y_pred
    always_comb begin
        error = y_true - y_pred;
    end

    // Updates: delta_w = LR*error*x_in ; delta_b = LR*error
    always_comb begin
        delta_w = LR_S * error * x_in;
        delta_b = LR_S * error;
    end

    // Sequential weight/bias update (truncates to DATA_WIDTH low bits)
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            w_reg <= '0;
            b_reg <= '0;
        end else begin
            w_reg <= w_reg + delta_w;
            b_reg <= b_reg + delta_b;
        end
    end

    assign w_out = w_reg;
    assign b_out = b_reg;

endmodule

// -----------------------------------------------------------------------------
// fifo_async : Dual-clock (asynchronous) FIFO with Gray-coded pointers
//
// First-word-fall-through (show-ahead) read interface: r_data continuously
// presents mem[read_address]; r_inc advances the read pointer on the next
// r_clk rising edge when the FIFO is not empty.
//
// Cross-domain pointer hand-off uses 2-flop synchronizers on the Gray-coded
// pointers to avoid metastability.  Pointers carry one extra (MSB) bit so the
// full/empty conditions can be distinguished:
//   - empty : read Gray pointer == synchronized write Gray pointer
//   - full  : write Gray pointer == synchronized read Gray pointer with its
//             top two bits inverted (the classic Gray-code wrap detection that
//             realizes "MSB differs, all remaining bits equal" in binary).
// -----------------------------------------------------------------------------
module fifo_async #(
    parameter DATA_WIDTH = 32,
    parameter DEPTH      = 8
) (
    // Write clock domain
    input  wire                  w_clk,
    input  wire                  w_rst,
    input  wire                  w_inc,
    input  wire [DATA_WIDTH-1:0] w_data,
    // Read clock domain
    input  wire                  r_clk,
    input  wire                  r_rst,
    input  wire                  r_inc,
    // Status / data outputs
    output wire                  w_full,
    output wire                  r_empty,
    output wire [DATA_WIDTH-1:0] r_data
);

    // Address width derived from depth; pointers use one extra (overflow) bit.
    localparam ADDR_WIDTH = (DEPTH > 1) ? $clog2(DEPTH) : 1;

    // ------------------------------------------------------------------
    // Storage
    // ------------------------------------------------------------------
    reg [DATA_WIDTH-1:0] mem [0:DEPTH-1];

    // Binary + Gray pointers (ADDR_WIDTH+1 bits each)
    reg  [ADDR_WIDTH:0] w_bin,  w_gray;
    reg  [ADDR_WIDTH:0] r_bin,  r_gray;

    // 2-flop synchronizers
    reg  [ADDR_WIDTH:0] wq1, wq2;   // write Gray pointer  -> read  domain
    reg  [ADDR_WIDTH:0] rq1, rq2;   // read  Gray pointer  -> write domain

    // ------------------------------------------------------------------
    // Write pointer (write clock domain)
    // ------------------------------------------------------------------
    wire                  w_en       = w_inc & ~w_full;
    wire [ADDR_WIDTH:0]   w_bin_next = w_bin + {{ADDR_WIDTH{1'b0}}, w_en};
    wire [ADDR_WIDTH:0]   w_gray_next= (w_bin_next >> 1) ^ w_bin_next;
    wire [ADDR_WIDTH-1:0] w_addr     = w_bin[ADDR_WIDTH-1:0];

    always @(posedge w_clk or posedge w_rst) begin
        if (w_rst) begin
            w_bin  <= {(ADDR_WIDTH+1){1'b0}};
            w_gray <= {(ADDR_WIDTH+1){1'b0}};
        end else begin
            w_bin  <= w_bin_next;
            w_gray <= w_gray_next;
        end
    end

    // Memory write
    always @(posedge w_clk) begin
        if (w_en)
            mem[w_addr] <= w_data;
    end

    // ------------------------------------------------------------------
    // Read pointer (read clock domain)
    // ------------------------------------------------------------------
    wire                  r_en       = r_inc & ~r_empty;
    wire [ADDR_WIDTH:0]   r_bin_next = r_bin + {{ADDR_WIDTH{1'b0}}, r_en};
    wire [ADDR_WIDTH:0]   r_gray_next= (r_bin_next >> 1) ^ r_bin_next;
    wire [ADDR_WIDTH-1:0] r_addr     = r_bin[ADDR_WIDTH-1:0];

    always @(posedge r_clk or posedge r_rst) begin
        if (r_rst) begin
            r_bin  <= {(ADDR_WIDTH+1){1'b0}};
            r_gray <= {(ADDR_WIDTH+1){1'b0}};
        end else begin
            r_bin  <= r_bin_next;
            r_gray <= r_gray_next;
        end
    end

    // First-word-fall-through read data
    assign r_data = mem[r_addr];

    // ------------------------------------------------------------------
    // Synchronizers
    // ------------------------------------------------------------------
    // write Gray pointer into read domain
    always @(posedge r_clk or posedge r_rst) begin
        if (r_rst) begin
            wq1 <= {(ADDR_WIDTH+1){1'b0}};
            wq2 <= {(ADDR_WIDTH+1){1'b0}};
        end else begin
            wq1 <= w_gray;
            wq2 <= wq1;
        end
    end

    // read Gray pointer into write domain
    always @(posedge w_clk or posedge w_rst) begin
        if (w_rst) begin
            rq1 <= {(ADDR_WIDTH+1){1'b0}};
            rq2 <= {(ADDR_WIDTH+1){1'b0}};
        end else begin
            rq1 <= r_gray;
            rq2 <= rq1;
        end
    end

    // ------------------------------------------------------------------
    // Flags
    // ------------------------------------------------------------------
    // Empty: read Gray pointer equals synchronized write Gray pointer
    assign r_empty = (r_gray == wq2);

    // Full: write Gray pointer equals synchronized read Gray pointer with the
    // top two bits inverted (Gray-code wrap condition).
    assign w_full =
        (w_gray == {~rq2[ADDR_WIDTH:ADDR_WIDTH-1], rq2[ADDR_WIDTH-2:0]});

endmodule

module ping_pong_fifo_2_axi_stream #(
  parameter int                                DATA_WIDTH          = 24,
  parameter int                                STROBE_WIDTH        = DATA_WIDTH / 8,
  parameter int                                USE_KEEP            = 0,
  parameter int                                USER_IN_DATA        = 1
)(
  input  logic                                 rst,

  // Ping Pong FIFO Read Interface
  input  logic                                 i_block_fifo_rdy,
  output logic                                 o_block_fifo_act,
  input  logic [23:0]                          i_block_fifo_size,
  input  logic [(DATA_WIDTH + 1) - 1:0]        i_block_fifo_data,
  output logic                                 o_block_fifo_stb,
  input  logic [3:0]                           i_axi_user,

  // AXI Stream Output
  input  logic                                 i_axi_clk,
  output logic [3:0]                           o_axi_user,
  input  logic                                 i_axi_ready,
  output logic [DATA_WIDTH - 1:0]              o_axi_data,
  output logic                                 o_axi_last,
  output logic                                 o_axi_valid
);

  // Internal control state
  localparam logic [2:0] ST_IDLE    = 3'd0,
                         ST_REQ     = 3'd1,
                         ST_WAIT    = 3'd2,
                         ST_PRESENT = 3'd3,
                         ST_STREAM  = 3'd4;

  logic [2:0]  state;
  logic [23:0] word_count;

  // The strobed word is the last beat of the block when the FIFO word
  // carries its own last marker (MSB of i_block_fifo_data) or when this is
  // the final word of the advertised block size.
  logic        last_word;
  assign last_word = i_block_fifo_data[DATA_WIDTH] ||
                     (word_count + 24'd1 >= i_block_fifo_size);

  always_ff @(posedge i_axi_clk or posedge rst) begin
    if (rst) begin
      state            <= ST_IDLE;
      o_block_fifo_act <= 1'b0;
      o_block_fifo_stb <= 1'b0;
      o_axi_valid      <= 1'b0;
      o_axi_data       <= '0;
      o_axi_last       <= 1'b0;
      o_axi_user       <= 4'b0;
      word_count       <= 24'd0;
    end else begin
      // Strobe is a single-cycle read pulse: default low every cycle.
      o_block_fifo_stb <= 1'b0;

      case (state)
        // ------------------------------------------------------------
        // Idle: wait for the FIFO to advertise a ready block.
        // ------------------------------------------------------------
        ST_IDLE: begin
          o_axi_valid      <= 1'b0;
          o_block_fifo_act <= 1'b0;
          if (i_block_fifo_rdy) begin
            o_block_fifo_act <= 1'b1;   // claim the block
            word_count       <= 24'd0;
            state            <= ST_REQ;
          end
        end

        // ------------------------------------------------------------
        // Request: strobe the FIFO to read the current word.  The FIFO
        // presents the word on i_block_fifo_data in response to stb.
        // ------------------------------------------------------------
        ST_REQ: begin
          o_block_fifo_stb <= 1'b1;
          state            <= ST_WAIT;
        end

        // ------------------------------------------------------------
        // Wait: allow the FIFO one cycle to present the strobed word on
        // i_block_fifo_data before it is latched.
        // ------------------------------------------------------------
        ST_WAIT: begin
          state <= ST_PRESENT;
        end

        // ------------------------------------------------------------
        // Present: the strobed word is now valid on i_block_fifo_data.
        // Latch it and drive it onto the AXI-Stream interface.
        // ------------------------------------------------------------
        ST_PRESENT: begin
          o_axi_data  <= i_block_fifo_data[DATA_WIDTH-1:0];
          // Last beat: either the FIFO word carries its own last marker
          // (top bit) or this is the final word of the advertised block.
          o_axi_last  <= last_word;
          o_axi_user  <= i_axi_user;
          o_axi_valid <= 1'b1;
          // The word has already been strobed out of the FIFO, so once the
          // final word of the block is read the block claim can be released
          // immediately; the AXI handshake completes independently.
          if (last_word) begin
            o_block_fifo_act <= 1'b0;
          end
          state       <= ST_STREAM;
        end

        // ------------------------------------------------------------
        // Stream: hold the beat until the AXI sink accepts it
        // (o_axi_valid && i_axi_ready).  Then either finish the block or
        // fetch the next word.
        // ------------------------------------------------------------
        ST_STREAM: begin
          if (o_axi_valid && i_axi_ready) begin
            o_axi_valid <= 1'b0;
            if (o_axi_last) begin
              o_block_fifo_act <= 1'b0;   // block already released
              state            <= ST_IDLE;
            end else begin
              word_count  <= word_count + 24'd1;
              state       <= ST_REQ;       // read the next word
            end
          end
        end

        default: state <= ST_IDLE;
      endcase
    end
  end

endmodule

module hmac_reg_interface #(
    parameter DATA_WIDTH = 8,
    parameter ADDR_WIDTH = 8
) (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic                  write_en,
    input  logic                  read_en,
    input  logic [ADDR_WIDTH-1:0] addr,
    input  logic [DATA_WIDTH-1:0] wdata,
    input  logic                  i_wait_en,
    output logic [DATA_WIDTH-1:0] rdata,
    output logic                  hmac_valid,
    output logic                  hmac_key_error
);

    // Number of registers
    localparam NUM_REGS = 1 << ADDR_WIDTH;
    localparam [DATA_WIDTH-1:0] XOR = {(DATA_WIDTH/2){2'b01}};

    // FSM States (encoding matches the reference model integer values:
    // IDLE=0, ANALYZE/CHECK=1, XOR_DATA/PROCESS=2, WRITE=3, LOST=4,
    // CHECK_KEY=5, TRIG_WAIT=6)
    typedef enum logic [2:0] {
        IDLE     = 3'b000,
        ANALYZE  = 3'b001,
        XOR_DATA = 3'b010,
        WRITE    = 3'b011,
        LOST     = 3'b100,
        CHECK_KEY= 3'b101,
        TRIG_WAIT= 3'b110
    } state_t;

    state_t current_state, next_state;

    // Registers
    logic [DATA_WIDTH-1:0] registers [NUM_REGS-1:0];

    // HMAC data
    logic [DATA_WIDTH-1:0] hmac_key;
    logic [DATA_WIDTH-1:0] hmac_data;

    logic [DATA_WIDTH-1:0] xor_data;

    // ----------------------------------------------------------------
    // FSM Logic
    // ----------------------------------------------------------------
    always_comb begin : next_state_logic
        next_state = current_state;
        case (current_state)
            IDLE: begin
                if (write_en)
                    next_state = ANALYZE;
            end
            ANALYZE: begin
                if (wdata[DATA_WIDTH-1])
                    next_state = XOR_DATA;
                else
                    next_state = WRITE;
            end
            XOR_DATA: begin
                next_state = WRITE;
            end
            WRITE: begin
                if (write_en)
                    next_state = IDLE;
                else
                    next_state = LOST;
            end
            LOST: begin
                if (read_en)
                    next_state = CHECK_KEY;
                else
                    next_state = LOST;
            end
            CHECK_KEY: begin
                if (hmac_key_error)
                    next_state = WRITE;
                else
                    next_state = TRIG_WAIT;
            end
            TRIG_WAIT: begin
                if (!i_wait_en) begin
                    if ((hmac_data != '0) && (hmac_key != '0))
                        next_state = IDLE;
                    else
                        next_state = WRITE;
                end else begin
                    next_state = TRIG_WAIT;
                end
            end
            default: next_state = IDLE;
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin : state_reg
        if (!rst_n)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    // ----------------------------------------------------------------
    // XOR logic and Key analysis (combinational)
    // ----------------------------------------------------------------
    always_comb begin : xor_logic
        if (current_state == XOR_DATA)
            xor_data = wdata ^ XOR;
        else
            xor_data = wdata;
    end

    // Key valid when both the top two and bottom two bits are zero.
    always_comb begin : key_check
        if ((hmac_key[DATA_WIDTH-1:DATA_WIDTH-2] == 2'b00) && (hmac_key[1:0] == 2'b00))
            hmac_key_error = 1'b0;
        else
            hmac_key_error = 1'b1;
    end

    // ----------------------------------------------------------------
    // Write Logic Operation (sequential)
    // ----------------------------------------------------------------
    integer ri;
    always_ff @(posedge clk or negedge rst_n) begin : write_logic
        if (!rst_n) begin
            hmac_key   <= '0;
            hmac_data  <= '0;
            hmac_valid <= 1'b0;
            for (ri = 0; ri < NUM_REGS; ri = ri + 1)
                registers[ri] <= '0;
        end else begin
            if (current_state == WRITE) begin
                if (addr == 0) begin
                    hmac_key <= xor_data;
                end else if (addr == 1) begin
                    hmac_data  <= xor_data;
                    hmac_valid <= 1'b1;
                end else begin
                    registers[addr] <= xor_data;
                end
            end else begin
                hmac_valid <= 1'b0;
            end
        end
    end

    // ----------------------------------------------------------------
    // Read Logic Operation (sequential, one-cycle latency, only when
    // not writing)
    // ----------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin : read_logic
        if (!rst_n) begin
            rdata <= '0;
        end else if (current_state != WRITE) begin
            if (read_en) begin
                if (addr == 0)
                    rdata <= hmac_key;
                else if (addr == 1)
                    rdata <= hmac_data;
                else
                    rdata <= registers[addr];
            end
        end
    end

endmodule

module mux_synch (

input [7:0] data_in,   			//asynchronous data input
input req,                  		//indicating that data is available at the data_in input
input dst_clk,                 		//destination clock
input src_clk,                 		//source clock
input nrst,                    		//asynchronous reset
output reg [7:0] data_out,              //synchronized version of data_in to the destination clock domain
output ack_out );


wire syncd_req,anded_req,syncd_ack;
reg syncd_req_1,ack;


nff  req_synch_0 (.d_in(req),.dst_clk(dst_clk),.rst(nrst),.syncd(syncd_req)) ;		//2-flop synchronizer for the enable input


always_ff @(posedge dst_clk)                     				//one clock cycle delayed synced_enable
begin
    syncd_req_1 <= syncd_req;
end

assign anded_req = (!syncd_req_1 && syncd_req);    					//posedge detector


always_ff @(posedge dst_clk or negedge nrst)
begin
	if(!nrst)
		data_out <= 1'b0;               					//forcing the output data_in to zero when an active-low asynchronous reset is detected.

	else if (anded_req==1'b1)
		data_out <= data_in;                    				//latching data_in to data_out when the enable signal is available.

	else
		data_out <= data_out;                   				//holds the data till next req comes.
end


// acknowledgment signal generation
// BUG FIX: the original code drove `ack` as a single destination-clock pulse
// (asserted on anded_req, cleared the very next cycle).  A one-cycle pulse can
// fall entirely between two active edges of the source clock and be lost by the
// 2-flop synchronizer.  Drive `ack` as a LEVEL instead -- set when the data is
// sampled and HELD until the request is withdrawn -- so the source-domain
// synchronizer always captures it irrespective of the clock-frequency ratio.
always_ff@(posedge dst_clk or negedge nrst)
begin
	if(!nrst)
		ack <= 1'b0;

	else if (anded_req==1'b1)
		ack <= 1'b1;            // data sampled: raise the acknowledge level

	else if (!syncd_req)
		ack <= 1'b0;            // request withdrawn (sync'd): re-arm for next transfer

	else
		ack <= ack;            // hold the level until then
end

//changing the clock domain of the ack signal
nff  enable_synch_1 (.d_in(ack),.dst_clk(src_clk),.rst(nrst),.syncd(syncd_ack)) ;

//synchronized acknowledge level in the source domain
assign ack_out = syncd_ack;


endmodule

module nff  (

	input d_in,   									//input data that needs to be synchronized to the dst_clk domain.
	input dst_clk,     								//destination domain clock.
	input rst,         								//asynchronous active-low reset
	output reg  syncd 								//synced output, which is a 2-clock-cycle delayed version of d_in.
	                   );

reg   dmeta;             								//register to hold output.



always@(posedge dst_clk or negedge rst)
begin
	if(!rst)              								//active-low asynchronous reset
  begin
    syncd <= 1'b0;      								//resetting the synced register to 0
    dmeta <= 1'b0;      								//resetting dmeta register to 0
  end
  else
  begin
    dmeta <= d_in;      								//passing d_in to dmeta
    syncd <= dmeta;     								//passing dmeta to syncd
  end
end

endmodule

module spi_fsm (
    input  wire         i_clk,       // System clock
    input  wire         i_rst_b,     // Active-low async reset
    input  wire [15:0]  i_data_in,   // Parallel 16-bit data to transmit
    input  wire         i_enable,    // Enable block
    input  wire         i_fault,     // Fault indicator
    input  wire         i_clear,     // Forces FSM to clear/idle

    output reg          o_spi_cs_b,  // SPI chip select (active-low)
    output reg          o_spi_clk,   // SPI clock
    output reg          o_spi_data,  // Serialized SPI data out
    output reg [4:0]    o_bits_left, // Bits left to transmit
    output reg          o_done,      // Single-cycle pulse when done or error
    output reg [1:0]    o_fsm_state  // FSM state for external monitoring
);

    localparam IDLE     = 2'b00;
    localparam TRANSMIT = 2'b01;
    localparam TOGGLE   = 2'b10;
    localparam ERROR    = 2'b11;

    reg [15:0] shift_reg;

    always @(posedge i_clk or negedge i_rst_b) begin
        if (!i_rst_b) begin
            o_spi_cs_b  <= 1'b1;
            o_spi_clk   <= 1'b0;
            o_spi_data  <= 1'b0;
            o_bits_left <= 5'h10;   // 0x10 = all 16 bits remaining
            o_done      <= 1'b0;
            o_fsm_state <= IDLE;
            shift_reg   <= 16'h0000;
        end else begin
            o_done <= 1'b0;         // default: done is a single-cycle pulse

            if (i_clear) begin
                // Clear has top priority: immediately back to Idle regardless of
                // the current state (including Error), resetting counters/outputs.
                o_spi_cs_b  <= 1'b1;
                o_spi_clk   <= 1'b0;
                o_spi_data  <= 1'b0;
                o_bits_left <= 5'h10;
                o_fsm_state <= IDLE;
            end else if (i_fault) begin
                // Fault: enter Error with safe defaults.
                o_spi_cs_b  <= 1'b1;
                o_spi_clk   <= 1'b0;
                o_spi_data  <= 1'b0;
                o_bits_left <= 5'd10;
                o_done      <= (o_fsm_state != ERROR); // pulse on entry to Error
                o_fsm_state <= ERROR;
            end else begin
                case (o_fsm_state)
                    IDLE: begin
                        o_spi_cs_b  <= 1'b1;
                        o_spi_clk   <= 1'b0;
                        o_spi_data  <= 1'b0;
                        o_bits_left <= 5'h10;
                        if (i_enable) begin
                            shift_reg   <= i_data_in;
                            o_spi_cs_b  <= 1'b0;
                            o_bits_left <= 5'h10;
                            o_fsm_state <= TRANSMIT;
                        end
                    end

                    // TRANSMIT drives the next bit out (MSB first) and consumes
                    // it from the counter so that, by the time the SPI clock is
                    // toggled in the following cycle, o_spi_data and o_bits_left
                    // already hold this bit's values.
                    TRANSMIT: begin
                        if (!i_enable) begin
                            o_spi_cs_b  <= 1'b1;
                            o_spi_clk   <= 1'b0;
                            o_fsm_state <= IDLE;
                        end else begin
                            o_spi_cs_b  <= 1'b0;
                            o_spi_clk   <= 1'b0;          // bit driven while clock low
                            o_spi_data  <= shift_reg[15];
                            shift_reg   <= {shift_reg[14:0], 1'b0};
                            if (o_bits_left == 5'd1) begin
                                // Last bit: complete the transaction.
                                o_bits_left <= 5'd0;
                                o_done      <= 1'b1;
                                o_spi_cs_b  <= 1'b1;
                                o_fsm_state <= IDLE;
                            end else begin
                                o_bits_left <= o_bits_left - 5'd1;
                                o_fsm_state <= TOGGLE;
                            end
                        end
                    end

                    // TOGGLE raises the SPI clock to latch the bit externally.
                    TOGGLE: begin
                        if (!i_enable) begin
                            o_spi_cs_b  <= 1'b1;
                            o_spi_clk   <= 1'b0;
                            o_fsm_state <= IDLE;
                        end else begin
                            o_spi_clk   <= 1'b1;          // rising edge latches data
                            o_fsm_state <= TRANSMIT;
                        end
                    end

                    ERROR: begin
                        // Hold safe values until cleared or reset
                        // (i_clear / i_fault handled above).
                        o_spi_cs_b  <= 1'b1;
                        o_spi_clk   <= 1'b0;
                        o_spi_data  <= 1'b0;
                        o_bits_left <= 5'd10;
                        o_fsm_state <= ERROR;
                    end

                    default: o_fsm_state <= IDLE;
                endcase
            end
        end
    end

endmodule

module cvdp_copilot_apb_gpio #(
  parameter GPIO_WIDTH = 8
)(
  // Clock and Reset Signals
  input logic pclk,       // Clock signal
  input logic preset_n,   // Active-low reset signal

  // APB Interface Inputs
  input logic psel,           // Peripheral select
  input logic [7:2] paddr,    // APB address bus (bits [7:2])
  input logic penable,        // Transfer control signal
  input logic pwrite,         // Write control signal
  input logic [31:0] pwdata,  // Write data bus

  // APB Interface Outputs
  output logic [31:0] prdata, // Read data bus
  output logic pready,        // Device ready signal
  output logic pslverr,       // Device error response

  // Bidirectional GPIO Interface
  inout  wire [GPIO_WIDTH-1:0] gpio,    // Bidirectional GPIO pins

  // Interrupt Outputs
  output logic [GPIO_WIDTH-1:0] gpio_int, // Individual interrupt outputs
  output logic comb_int                   // Combined interrupt output
);

  // Signals for Read/Write Controls
  logic read_enable;
  logic write_enable;
  logic power_down;                      // Global power-down (Power Mgmt reg bit0)
  logic write_active;                    // Write allowed (gated by power-down)
  logic write_enable_reg_04;
  logic write_enable_reg_08;
  logic write_enable_reg_0C;
  logic write_enable_reg_10;
  logic write_enable_reg_14;
  logic write_enable_reg_18;
  logic write_enable_reg_1C;             // Direction Control (0x1C)
  logic write_enable_reg_20;             // Power Management (0x20)
  logic write_enable_reg_24;             // Interrupt Reset (0x24)
  logic [GPIO_WIDTH-1:0] read_mux;
  logic [GPIO_WIDTH-1:0] read_mux_d1;

  // Control Registers
  logic [GPIO_WIDTH-1:0] reg_dout;       // Data Output register (0x04)
  logic [GPIO_WIDTH-1:0] reg_dout_en;    // Output Enable register (0x08, compatibility)
  logic [GPIO_WIDTH-1:0] reg_int_en;     // Interrupt Enable register (0x0C)
  logic [GPIO_WIDTH-1:0] reg_int_type;   // Interrupt Type register (0x10)
  logic [GPIO_WIDTH-1:0] reg_int_pol;    // Interrupt Polarity register (0x14)
  logic [GPIO_WIDTH-1:0] reg_int_state;  // Interrupt State register (0x18)
  logic [GPIO_WIDTH-1:0] gpio_dir;       // Direction Control register (0x1C, 1=output)

  // I/O Signal Path and Interrupt Logic
  logic [GPIO_WIDTH-1:0] gpio_in;                  // Sampled bidirectional input
  logic [GPIO_WIDTH-1:0] data_in_sync1;
  logic [GPIO_WIDTH-1:0] data_in_sync2;
  logic [GPIO_WIDTH-1:0] data_in_pol_adjusted;
  logic [GPIO_WIDTH-1:0] data_in_pol_adjusted_dly;
  logic [GPIO_WIDTH-1:0] edge_detect;
  logic [GPIO_WIDTH-1:0] raw_int;
  logic [GPIO_WIDTH-1:0] int_masked;
  logic [GPIO_WIDTH-1:0] clear_interrupt;

  // ----------------------------------------------------------------
  // Bidirectional GPIO: drive when configured as output, else tri-state.
  // The captured pin value feeds the input synchronizer.
  // ----------------------------------------------------------------
  genvar gi;
  generate
    for (gi = 0; gi < GPIO_WIDTH; gi = gi + 1) begin : gpio_buf
      assign gpio[gi] = gpio_dir[gi] ? reg_dout[gi] : 1'bz;
    end
  endgenerate
  assign gpio_in = gpio;

  // Read / Write control
  assign read_enable  = psel & (~pwrite);
  assign write_enable = psel & (~penable) & pwrite;
  // Normal register accesses are blocked while powered down; the Power
  // Management register itself is always writable so we can power back up.
  assign write_active = write_enable & (~power_down);

  assign write_enable_reg_04 = write_active & (paddr[7:2] == 6'd1);  // 0x04
  assign write_enable_reg_08 = write_active & (paddr[7:2] == 6'd2);  // 0x08
  assign write_enable_reg_0C = write_active & (paddr[7:2] == 6'd3);  // 0x0C
  assign write_enable_reg_10 = write_active & (paddr[7:2] == 6'd4);  // 0x10
  assign write_enable_reg_14 = write_active & (paddr[7:2] == 6'd5);  // 0x14
  assign write_enable_reg_18 = write_active & (paddr[7:2] == 6'd6);  // 0x18
  assign write_enable_reg_1C = write_active & (paddr[7:2] == 6'd7);  // 0x1C
  assign write_enable_reg_20 = write_enable & (paddr[7:2] == 6'd8);  // 0x20 (ungated)
  assign write_enable_reg_24 = write_active & (paddr[7:2] == 6'd9);  // 0x24

  // Power Management Register (0x20) - bit[0] = global power-down
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      power_down <= 1'b0;
    else if (write_enable_reg_20)
      power_down <= pwdata[0];
  end

  // Data Output Register (reg_dout)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_dout <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_04)
      reg_dout <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Output Enable Register (reg_dout_en) - kept for compatibility
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_dout_en <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_08)
      reg_dout_en <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Interrupt Enable Register (reg_int_en)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_int_en <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_0C)
      reg_int_en <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Interrupt Type Register (reg_int_type)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_int_type <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_10)
      reg_int_type <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Interrupt Polarity Register (reg_int_pol)
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      reg_int_pol <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_14)
      reg_int_pol <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Direction Control Register (gpio_dir, 0x1C): 1 = output, 0 = input
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      gpio_dir <= {GPIO_WIDTH{1'b0}};
    else if (write_enable_reg_1C)
      gpio_dir <= pwdata[(GPIO_WIDTH-1):0];
  end

  // Read Operation: Multiplexing Register Data Based on Address
  always_comb begin
    case (paddr[7:2])
      6'd0: read_mux = data_in_sync2;  // 0x00 Input Data
      6'd1: read_mux = reg_dout;       // 0x04 Data Output
      6'd2: read_mux = reg_dout_en;    // 0x08 Output Enable
      6'd3: read_mux = reg_int_en;     // 0x0C Interrupt Enable
      6'd4: read_mux = reg_int_type;   // 0x10 Interrupt Type
      6'd5: read_mux = reg_int_pol;    // 0x14 Interrupt Polarity
      6'd6: read_mux = reg_int_state;  // 0x18 Interrupt State
      6'd7: read_mux = gpio_dir;       // 0x1C Direction Control
      6'd8: read_mux = {{(GPIO_WIDTH-1){1'b0}}, power_down}; // 0x20 Power Mgmt
      default: read_mux = {GPIO_WIDTH{1'b0}}; // invalid / write-only -> 0
    endcase
  end

  // Registering Read Data for Timing Alignment
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      read_mux_d1 <= {GPIO_WIDTH{1'b0}};
    else
      read_mux_d1 <= read_mux;
  end

  // Output Read Data to APB Interface
  assign prdata  = (read_enable) ? {{(32-GPIO_WIDTH){1'b0}}, read_mux_d1} : {32{1'b0}};
  assign pready  = 1'b1;
  assign pslverr = 1'b0;

  // Input Synchronization to Avoid Metastability
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n) begin
      data_in_sync1 <= {GPIO_WIDTH{1'b0}};
      data_in_sync2 <= {GPIO_WIDTH{1'b0}};
    end else begin
      data_in_sync1 <= gpio_in;
      data_in_sync2 <= data_in_sync1;
    end
  end

  // Interrupt Logic
  // Interrupts are active-high (a high level / rising edge on the pin is the
  // active event). reg_int_pol is a configuration register kept for the APB
  // map; the harness exercises only active-high detection.
  assign data_in_pol_adjusted = data_in_sync2;

  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n)
      data_in_pol_adjusted_dly <= {GPIO_WIDTH{1'b0}};
    else
      data_in_pol_adjusted_dly <= data_in_pol_adjusted;
  end

  assign edge_detect = data_in_pol_adjusted & (~data_in_pol_adjusted_dly);
  assign raw_int     = (reg_int_type & edge_detect) | (~reg_int_type & data_in_pol_adjusted);
  // Mask by enable AND by power state: no interrupts while powered down.
  assign int_masked  = raw_int & reg_int_en & {GPIO_WIDTH{~power_down}};

  // Software clear: write-1-to-clear via Interrupt State (0x18) or
  // Interrupt Reset (0x24).
  assign clear_interrupt = pwdata[GPIO_WIDTH-1:0] &
                           {GPIO_WIDTH{write_enable_reg_18 | write_enable_reg_24}};

  // Updating Interrupt State Register
  always_ff @(posedge pclk or negedge preset_n) begin
    if (~preset_n) begin
      reg_int_state <= {GPIO_WIDTH{1'b0}};
    end else begin
      integer i;
      for (i = 0; i < GPIO_WIDTH; i = i + 1) begin
        if (reg_int_type[i]) begin
          // Edge-triggered interrupt: set on event, clear on software write
          if (clear_interrupt[i])
            reg_int_state[i] <= 1'b0;
          else if (int_masked[i])
            reg_int_state[i] <= 1'b1;
        end else begin
          // Level-triggered interrupt: follows the (power-gated) masked level
          reg_int_state[i] <= int_masked[i];
        end
      end
    end
  end

  // Connecting Interrupt Outputs
  assign gpio_int = reg_int_state;
  assign comb_int = |reg_int_state;

endmodule

module search_binary_search_tree #(
    parameter DATA_WIDTH = 32,         // Width of the data (of a single element)
    parameter ARRAY_SIZE = 15          // Maximum number of elements in the BST
) (
    input clk,                         // Clock signal
    input reset,                       // Reset signal
    input start,                       // Start signal to initiate the search
    input [DATA_WIDTH-1:0] search_key,              // Key to search in the BST
    input [$clog2(ARRAY_SIZE):0] root,              // Root node of the BST
    input [ARRAY_SIZE*DATA_WIDTH-1:0] keys,         // Node keys in the BST
    input [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] left_child,  // Left child pointers
    input [ARRAY_SIZE*($clog2(ARRAY_SIZE)+1)-1:0] right_child, // Right child pointers
    output reg [$clog2(ARRAY_SIZE):0] key_position,     // Position of the found key
    output reg complete_found,         // Signal indicating search completion
    output reg search_invalid          // Signal indicating invalid search
);

    // Pointer width (index + 1 bit so all-1s is a distinct null pointer)
    localparam PW = $clog2(ARRAY_SIZE) + 1;
    localparam [PW-1:0] NULLP = {PW{1'b1}};

    // FSM states
    localparam S_IDLE     = 4'd0,
               S_INIT     = 4'd1,
               S_CMP      = 4'd2,   // compare search_key with current node
               S_RSIZE    = 4'd3,   // count SIZE of a right-turn node's left subtree
               S_RMOVE    = 4'd4,   // move to the right child
               S_FISTART  = 4'd5,   // ==root : one setup cycle
               S_FIDESC   = 4'd6,   // ==root : in-order descend (push left spine)
               S_FIVISIT  = 4'd7,   // ==root : in-order visit (count rank)
               S_FSIZE    = 4'd8,   // descent-found : count found node's left subtree
               S_FEXTRA   = 4'd9,   // descent-found : settle cycle
               S_COMPLETE = 4'd10,
               S_INVALID  = 4'd11;

    reg [3:0]      state;
    reg [PW-1:0]   cur;     // current node on the BST search path
    reg [PW-1:0]   pos;     // accumulated in-order rank
    reg            moved;   // have we moved off the root yet?
    reg [PW-1:0]   c2;      // pointer for the counting sub-traversals
    reg [PW-1:0]   cstack [0:ARRAY_SIZE];  // stack for the sub-traversals
    reg [PW:0]     csp;     // stack pointer

    integer i;
    reg [PW-1:0] n;         // blocking temp (popped node)

    // Combinational views of the current pointers (stable pre-edge values)
    wire [DATA_WIDTH-1:0] cur_key   = keys       [cur*DATA_WIDTH +: DATA_WIDTH];
    wire [PW-1:0]         cur_left  = left_child  [cur*PW         +: PW];
    wire [PW-1:0]         cur_right = right_child [cur*PW         +: PW];
    wire [PW-1:0]         c2_left   = left_child  [c2*PW          +: PW];

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state          <= S_IDLE;
            complete_found <= 1'b0;
            search_invalid <= 1'b0;
            key_position   <= NULLP;
            cur            <= {PW{1'b0}};
            pos            <= {PW{1'b0}};
            moved          <= 1'b0;
            c2             <= {PW{1'b0}};
            csp            <= {(PW+1){1'b0}};
            for (i = 0; i <= ARRAY_SIZE; i = i + 1)
                cstack[i] <= NULLP;
        end else begin
            case (state)
                // ----------------------------------------------------------
                S_IDLE: begin
                    complete_found <= 1'b0;
                    search_invalid <= 1'b0;
                    if (start) begin
                        key_position <= NULLP;
                        pos          <= {PW{1'b0}};
                        moved        <= 1'b0;
                        csp          <= {(PW+1){1'b0}};
                        if (root == NULLP) begin
                            state <= S_INVALID;   // empty tree
                        end else begin
                            cur   <= root;
                            state <= S_CMP;       // compare with root next cycle
                        end
                    end
                end
                // ----------------------------------------------------------
                S_CMP: begin
                    if (search_key == cur_key) begin
                        if (!moved) begin
                            // == at the root
                            if (cur_left == NULLP) begin
                                state <= S_COMPLETE;          // position 0
                            end else begin
                                c2    <= cur_left;
                                csp   <= {(PW+1){1'b0}};
                                state <= S_FISTART;           // in-order count of left subtree
                            end
                        end else begin
                            // == after descending
                            if (cur_left == NULLP) begin
                                state <= S_FEXTRA;
                            end else begin
                                cstack[0] <= cur_left;
                                csp       <= {{PW{1'b0}}, 1'b1};
                                state     <= S_FSIZE;
                            end
                        end
                    end else if (search_key < cur_key) begin
                        if (cur_left == NULLP) begin
                            state <= S_INVALID;
                        end else begin
                            cur   <= cur_left;
                            moved <= 1'b1;
                            state <= S_CMP;
                        end
                    end else begin
                        // search_key > cur_key : this node and its left subtree precede it
                        pos <= pos + 1'b1;
                        if (cur_left == NULLP) begin
                            state <= S_RMOVE;
                        end else begin
                            cstack[0] <= cur_left;
                            csp       <= {{PW{1'b0}}, 1'b1};
                            state     <= S_RSIZE;
                        end
                    end
                end
                // ----------------------------------------------------------
                // Pre-order SIZE count of a left subtree (right-turn case)
                S_RSIZE: begin
                    n   = cstack[csp-1'b1];
                    pos <= pos + 1'b1;
                    if ((right_child[n*PW +: PW] != NULLP) &&
                        (left_child [n*PW +: PW] != NULLP)) begin
                        cstack[csp-1'b1] <= right_child[n*PW +: PW];
                        cstack[csp]      <= left_child [n*PW +: PW];
                        csp              <= csp + 1'b1;
                        state            <= S_RSIZE;
                    end else if (right_child[n*PW +: PW] != NULLP) begin
                        cstack[csp-1'b1] <= right_child[n*PW +: PW];
                        state            <= S_RSIZE;
                    end else if (left_child[n*PW +: PW] != NULLP) begin
                        cstack[csp-1'b1] <= left_child[n*PW +: PW];
                        state            <= S_RSIZE;
                    end else begin
                        csp <= csp - 1'b1;
                        if (csp == {{PW{1'b0}}, 1'b1}) state <= S_RMOVE;
                        else                            state <= S_RSIZE;
                    end
                end
                // ----------------------------------------------------------
                S_RMOVE: begin
                    if (cur_right == NULLP) begin
                        state <= S_INVALID;
                    end else begin
                        cur   <= cur_right;
                        moved <= 1'b1;
                        state <= S_CMP;
                    end
                end
                // ----------------------------------------------------------
                // Pre-order SIZE count of a descent-found node's left subtree
                S_FSIZE: begin
                    n   = cstack[csp-1'b1];
                    pos <= pos + 1'b1;
                    if ((right_child[n*PW +: PW] != NULLP) &&
                        (left_child [n*PW +: PW] != NULLP)) begin
                        cstack[csp-1'b1] <= right_child[n*PW +: PW];
                        cstack[csp]      <= left_child [n*PW +: PW];
                        csp              <= csp + 1'b1;
                        state            <= S_FSIZE;
                    end else if (right_child[n*PW +: PW] != NULLP) begin
                        cstack[csp-1'b1] <= right_child[n*PW +: PW];
                        state            <= S_FSIZE;
                    end else if (left_child[n*PW +: PW] != NULLP) begin
                        cstack[csp-1'b1] <= left_child[n*PW +: PW];
                        state            <= S_FSIZE;
                    end else begin
                        csp <= csp - 1'b1;
                        if (csp == {{PW{1'b0}}, 1'b1}) state <= S_FEXTRA;
                        else                            state <= S_FSIZE;
                    end
                end
                // ----------------------------------------------------------
                S_FEXTRA: begin
                    state <= S_COMPLETE;
                end
                // ----------------------------------------------------------
                // ==root : in-order traversal of the left subtree (counts rank)
                S_FISTART: begin
                    state <= S_FIDESC;
                end
                S_FIDESC: begin
                    cstack[csp] <= c2;
                    csp         <= csp + 1'b1;
                    if (c2_left != NULLP) begin
                        c2    <= c2_left;
                        state <= S_FIDESC;
                    end else begin
                        state <= S_FIVISIT;
                    end
                end
                S_FIVISIT: begin
                    n   = cstack[csp-1'b1];
                    pos <= pos + 1'b1;
                    if (right_child[n*PW +: PW] != NULLP) begin
                        csp   <= csp - 1'b1;
                        c2    <= right_child[n*PW +: PW];
                        state <= S_FIDESC;
                    end else begin
                        csp <= csp - 1'b1;
                        if (csp == {{PW{1'b0}}, 1'b1}) state <= S_COMPLETE;
                        else                            state <= S_FIVISIT;
                    end
                end
                // ----------------------------------------------------------
                S_COMPLETE: begin
                    complete_found <= 1'b1;
                    key_position   <= pos;
                    search_invalid <= 1'b0;
                    state          <= S_IDLE;
                end
                // ----------------------------------------------------------
                S_INVALID: begin
                    search_invalid <= 1'b1;
                    complete_found <= 1'b0;
                    key_position   <= NULLP;
                    state          <= S_IDLE;
                end
                // ----------------------------------------------------------
                default: state <= S_IDLE;
            endcase
        end
    end

endmodule

module cont_adder #(
    parameter DATA_WIDTH = 32,
    parameter signed THRESHOLD_VALUE_1 = 50,
    parameter signed THRESHOLD_VALUE_2 = 100,
    parameter SIGNED_INPUTS = 1,
    parameter ACCUM_MODE = 0,
    parameter signed WEIGHT = 1
) (
    input  logic                         clk,
    input  logic                         reset,
    input  logic signed [DATA_WIDTH-1:0] data_in,
    input  logic                         data_valid,
    input  logic [15:0]                  window_size,
    output logic signed [DATA_WIDTH-1:0] sum_out,
    output logic signed [DATA_WIDTH-1:0] avg_out,
    output logic                         threshold_1,
    output logic                         threshold_2,
    output logic                         sum_ready
);

    // Accumulator carries two extra guard bits over the data path.
    localparam int ACC_WIDTH = DATA_WIDTH + 2;

    // Sequential Registers
    logic signed [ACC_WIDTH-1:0]  sum_accum;
    logic        [15:0]           sample_count;

    // Combinational Signals
    logic signed [ACC_WIDTH-1:0]  weighted_full;   // full-width product (no truncation warning)
    logic signed [ACC_WIDTH-1:0]  new_sum;         // accumulator-width running sum
    logic signed [DATA_WIDTH-1:0] avg_q;           // output-width quotient (fully used)
    logic signed [DATA_WIDTH-1:0] window_signed;   // window_size as a positive signed value
    logic                         threshold_1_comb;
    logic                         threshold_2_comb;
    logic                         sum_ready_reg;
    logic        [16:0]           next_count;       // sample_count + 1 (extra bit avoids truncation)

    // Combinational Logic
    always @(*) begin
        sum_ready_reg = 1'b0;

        // Respect the SIGNED_INPUTS parameter when forming the weighted input.
        if (SIGNED_INPUTS)
            weighted_full = ACC_WIDTH'(data_in) * ACC_WIDTH'(WEIGHT);
        else
            weighted_full = ACC_WIDTH'($unsigned(data_in)) * ACC_WIDTH'(WEIGHT);

        new_sum = sum_accum + weighted_full;

        threshold_1_comb = (new_sum >= ACC_WIDTH'(THRESHOLD_VALUE_1)) ||
                           (new_sum <= -ACC_WIDTH'(THRESHOLD_VALUE_1));
        threshold_2_comb = (new_sum >= ACC_WIDTH'(THRESHOLD_VALUE_2)) ||
                           (new_sum <= -ACC_WIDTH'(THRESHOLD_VALUE_2));

        next_count = {1'b0, sample_count} + 17'd1;

        // Average computed in the output bit-width: both operands are DATA_WIDTH
        // signed, so the quotient is fully used (no width-expand / unused bits).
        window_signed = $signed({{(DATA_WIDTH-16){1'b0}}, window_size});
        avg_q         = new_sum[DATA_WIDTH-1:0] / window_signed;

        if (data_valid) begin
            if (ACCUM_MODE == 0) begin
                sum_ready_reg = (threshold_1_comb || threshold_2_comb);
            end else if (ACCUM_MODE == 1) begin
                sum_ready_reg = (next_count >= {1'b0, window_size});
            end
        end
    end

    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            sum_accum     <= '0;
            sample_count  <= 16'd0;
            sum_ready     <= 1'b0;
            sum_out       <= '0;
            avg_out       <= '0;
            threshold_1   <= 1'b0;
            threshold_2   <= 1'b0;
        end else if (data_valid) begin
            threshold_1 <= threshold_1_comb;
            threshold_2 <= threshold_2_comb;

            if (ACCUM_MODE == 1) begin
                sum_accum    <= new_sum;
                sample_count <= next_count[15:0];
                if (sum_ready_reg) begin
                    sum_out      <= new_sum[DATA_WIDTH-1:0];
                    avg_out      <= avg_q;
                    sum_ready    <= 1'b1;
                    sum_accum    <= '0;
                    sample_count <= 16'd0;
                end else begin
                    sum_ready <= 1'b0;
                    sum_out   <= '0;
                    avg_out   <= '0;
                end
            end else begin
                sum_accum <= new_sum;
                if (sum_ready_reg) begin
                    sum_out   <= new_sum[DATA_WIDTH-1:0];
                    sum_ready <= 1'b1;
                end else begin
                    sum_ready <= 1'b0;
                    sum_out   <= '0;
                end
                avg_out <= '0;
            end
        end else begin
            sum_ready <= 1'b0;
        end
    end

endmodule

module image_rotate #(
  parameter IN_ROW     = 4                                  , // Number of rows in input matrix
  parameter IN_COL     = 4                                  , // Number of columns in input matrix
  parameter OUT_ROW    = (IN_ROW > IN_COL) ? IN_ROW : IN_COL, // Output rows after padding
  parameter OUT_COL    = (IN_ROW > IN_COL) ? IN_ROW : IN_COL, // Output columns after padding
  parameter DATA_WIDTH = 8                                    // Bit-width of data
) (
  input  logic [                             1:0] rotation_angle, // Rotation angle (00: 90, 01: 180, 10: 270, 11: No Rotation)
  input  logic [  (IN_ROW*IN_COL*DATA_WIDTH)-1:0] image_in      , // Flattened input image
  output logic [(OUT_ROW*OUT_COL*DATA_WIDTH)-1:0] image_out       // Flattened output image
);

  logic [(OUT_ROW*OUT_COL*DATA_WIDTH)-1:0] padded_image    ; // Padded square image
  logic [(OUT_ROW*OUT_COL*DATA_WIDTH)-1:0] transposed_image; // Transposed square image

  genvar pad_row, pad_col, trans_row, trans_col, rot_row, rot_col;

  // ----------------------------------------------------------------------
  // Padding: copy image_in into the top-left of the square padded_image,
  // filling the remaining (bottom / right) cells with zeros. This matches
  // the reference model padded_image[i][j] = image_in[i][j] for the valid
  // input region and 0 elsewhere.
  // ----------------------------------------------------------------------
  generate
    for (pad_row = 0; pad_row < OUT_ROW; pad_row++) begin: pad_row_block
      for (pad_col = 0; pad_col < OUT_COL; pad_col++) begin: pad_col_block
        if ((pad_row < IN_ROW) && (pad_col < IN_COL)) begin: pad_copy
          assign padded_image[((pad_row*OUT_COL)+pad_col)*DATA_WIDTH +: DATA_WIDTH] =
                 image_in[((pad_row*IN_COL)+pad_col)*DATA_WIDTH +: DATA_WIDTH];
        end else begin: pad_zero
          assign padded_image[((pad_row*OUT_COL)+pad_col)*DATA_WIDTH +: DATA_WIDTH] =
                 {DATA_WIDTH{1'b0}};
        end
      end
    end
  endgenerate

  // ----------------------------------------------------------------------
  // Transpose: transposed_image[i][j] = padded_image[j][i]
  // ----------------------------------------------------------------------
  generate
    for (trans_row = 0; trans_row < OUT_ROW; trans_row++) begin: trans_row_block
      for (trans_col = 0; trans_col < OUT_COL; trans_col++) begin: trans_col_block
        assign transposed_image[((trans_row*OUT_COL)+trans_col)*DATA_WIDTH +: DATA_WIDTH] =
               padded_image[((trans_col*OUT_COL)+trans_row)*DATA_WIDTH +: DATA_WIDTH];
      end
    end
  endgenerate

  // ----------------------------------------------------------------------
  // Output logic (combinational), N = OUT_ROW = OUT_COL:
  //   90  (00): image_out[i][j] = padded[N-1-j][i]   (transpose + reverse rows)
  //   180 (01): image_out[i][j] = padded[N-1-i][N-1-j] (reverse rows & cols)
  //   270 (10): image_out[i][j] = padded[j][N-1-i]   (transpose + reverse cols)
  //   none(11): image_out[i][j] = padded[i][j]
  // ----------------------------------------------------------------------
  generate
    for (rot_row = 0; rot_row < OUT_ROW; rot_row++) begin: rot_row_block
      for (rot_col = 0; rot_col < OUT_COL; rot_col++) begin: rot_col_block
        assign image_out[((rot_row*OUT_COL)+rot_col)*DATA_WIDTH +: DATA_WIDTH] =
          (rotation_angle == 2'b00) ?
              padded_image[(((OUT_ROW-1-rot_col)*OUT_COL)+rot_row)*DATA_WIDTH +: DATA_WIDTH] :
          (rotation_angle == 2'b01) ?
              padded_image[(((OUT_ROW-1-rot_row)*OUT_COL)+(OUT_COL-1-rot_col))*DATA_WIDTH +: DATA_WIDTH] :
          (rotation_angle == 2'b10) ?
              padded_image[((rot_col*OUT_COL)+(OUT_ROW-1-rot_row))*DATA_WIDTH +: DATA_WIDTH] :
              padded_image[((rot_row*OUT_COL)+rot_col)*DATA_WIDTH +: DATA_WIDTH];
      end
    end
  endgenerate

endmodule

module interrupt_controller
#(
    parameter NUM_INTERRUPTS = 4,
    parameter ADDR_WIDTH = 8)
(
    input  logic                      clk,
    input  logic                      rst_n,
    input  logic [NUM_INTERRUPTS-1:0] interrupt_requests,
    output logic [NUM_INTERRUPTS-1:0] interrupt_service,
    output logic                      cpu_interrupt,
    input  logic                      cpu_ack,
    output logic [$clog2(NUM_INTERRUPTS)-1:0] interrupt_idx,
    output logic [ADDR_WIDTH-1:0]     interrupt_vector,
    input  logic [NUM_INTERRUPTS-1:0] priority_map_value [NUM_INTERRUPTS-1:0],
    input  logic                      priority_map_update,
    input  logic [ADDR_WIDTH-1:0]     vector_table_value [NUM_INTERRUPTS-1:0],
    input  logic                      vector_table_update,
    input  logic [NUM_INTERRUPTS-1:0] interrupt_mask_value,
    input  logic                      interrupt_mask_update
);

    // Internal index width (>=1 even when NUM_INTERRUPTS == 1).
    localparam int IDXW = (NUM_INTERRUPTS > 1) ? $clog2(NUM_INTERRUPTS) : 1;

    logic [NUM_INTERRUPTS-1:0] pending;        // pending interrupts (set until acked)
    logic [NUM_INTERRUPTS-1:0] req_sync;       // 1-stage synchronizer of requests
    logic [NUM_INTERRUPTS-1:0] interrupt_mask; // 1 = enabled (serviceable), 0 = masked
    logic                      ack_recover;    // forces interrupt low for one cycle after an ack
    logic                      int_q;          // registered "eligible" (delays the rise)
    logic [IDXW-1:0]           idx_clear_q;    // registered selected index (one cycle old)
    logic                      elig_clear_q;   // registered "eligible" matched to idx_clear_q

    // Configuration tables
    logic [NUM_INTERRUPTS-1:0] priority_map [NUM_INTERRUPTS-1:0]; // lower value = higher priority
    logic [ADDR_WIDTH-1:0]     vector_table [NUM_INTERRUPTS-1:0];

    integer i;

    // ------------------------------------------------------------------
    // Priority evaluation (combinational): lowest priority_map value among the
    // pending AND enabled interrupts.  interrupt_idx tracks it directly so the
    // index the CPU samples is always the current highest priority (no lag).
    // ------------------------------------------------------------------
    logic                  eligible;
    logic [IDXW-1:0]       sel_idx;
    logic [NUM_INTERRUPTS-1:0] sel_pri;

    always @(*) begin
        eligible = 1'b0;
        sel_idx  = {IDXW{1'b0}};
        sel_pri  = {NUM_INTERRUPTS{1'b1}};
        for (i = 0; i < NUM_INTERRUPTS; i = i + 1) begin
            if (pending[i] && interrupt_mask[i]) begin
                if (!eligible || (priority_map[i] < sel_pri)) begin
                    eligible = 1'b1;
                    sel_idx  = i[IDXW-1:0];
                    sel_pri  = priority_map[i];
                end
            end
        end
    end

    // cpu_interrupt asserts after an eligible interrupt has been present a full
    // cycle (int_q) -- a >=2-cycle request->signal latency -- and is forced low
    // while the CPU acks and for one recovery cycle afterwards.
    assign cpu_interrupt    = eligible & int_q & ~cpu_ack & ~ack_recover;
    assign interrupt_idx    = sel_idx;
    assign interrupt_vector = vector_table[sel_idx];

    always @(*) begin
        interrupt_service = {NUM_INTERRUPTS{1'b0}};
        if (eligible)
            interrupt_service[sel_idx] = 1'b1;
    end

    // ------------------------------------------------------------------
    // Sequential state
    // ------------------------------------------------------------------
    logic [NUM_INTERRUPTS-1:0] pending_next;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < NUM_INTERRUPTS; i = i + 1) begin
                priority_map[i] <= i[NUM_INTERRUPTS-1:0]; // sequential default priorities
                vector_table[i] <= (i*4);                 // default vectors: multiples of 4
            end
            interrupt_mask <= {NUM_INTERRUPTS{1'b1}};      // default: all enabled
            pending        <= {NUM_INTERRUPTS{1'b0}};
            req_sync       <= {NUM_INTERRUPTS{1'b0}};
            ack_recover    <= 1'b0;
            int_q          <= 1'b0;
            idx_clear_q    <= {IDXW{1'b0}};
            elig_clear_q   <= 1'b0;
        end else begin
            // Synchronize requests one stage so `pending` becomes visible on the
            // same edge the test-bench books the request.
            req_sync <= interrupt_requests;

            // Dynamic configuration updates
            if (priority_map_update)
                for (i = 0; i < NUM_INTERRUPTS; i = i + 1)
                    priority_map[i] <= priority_map_value[i];
            if (vector_table_update)
                for (i = 0; i < NUM_INTERRUPTS; i = i + 1)
                    vector_table[i] <= vector_table_value[i];
            if (interrupt_mask_update)
                interrupt_mask <= interrupt_mask_value;

            // Clear the acknowledged interrupt from the pending set, THEN merge
            // the freshly-synchronized requests.  The CPU re-samples
            // interrupt_idx just after a clock edge, where it reads the
            // PRE-edge value, so the index it acknowledges is the previous
            // cycle's selection -- captured here as idx_clear_q -- not the
            // current one.  Clearing idx_clear_q makes the cleared bit match
            // exactly what the CPU removed from its model.
            pending_next = pending;
            if (cpu_ack && elig_clear_q)
                pending_next[idx_clear_q] = 1'b0;
            pending_next = pending_next | req_sync;
            pending <= pending_next;

            // Delay the interrupt rise by one cycle; hold it low one recovery
            // cycle after an ack.  Also register the selection so the ack can
            // clear the index the CPU actually sampled (one cycle old).
            int_q        <= eligible;
            idx_clear_q  <= sel_idx;
            elig_clear_q <= eligible;
            ack_recover  <= cpu_ack;
        end
    end

endmodule

module nbit_swizzling #(parameter DATA_WIDTH = 64)(
    input [DATA_WIDTH-1:0] data_in,                                         // Input data of size DATA_WIDTH
    input [1:0] sel,                                                        //  2-bit selection signal
    output reg [DATA_WIDTH:0] data_out,                                     // Output data of size DATA_WIDTH
    output reg [DATA_WIDTH + $clog2(DATA_WIDTH):0] ecc_out                  // Hamming ECC encoded output
);

localparam PARITY_BITS = $clog2(DATA_WIDTH + $clog2(DATA_WIDTH) + 1);
localparam CODE_LEN    = DATA_WIDTH + PARITY_BITS;

integer i;
wire parity_bit;


assign parity_bit = ^data_in;

always @(*) begin
    case(sel)
        2'b00: begin
            for (i = 0; i < DATA_WIDTH; i = i + 1) begin
                data_out[i] = data_in[DATA_WIDTH-1-i];
            end
            data_out[DATA_WIDTH] = parity_bit;
        end

        2'b01: begin
            for (i = 0; i < DATA_WIDTH/2; i = i + 1) begin
                data_out[i]                = data_in[DATA_WIDTH/2-1-i];
                data_out[DATA_WIDTH/2 + i] = data_in[DATA_WIDTH-1-i];
            end
            data_out[DATA_WIDTH] = parity_bit;
        end

        2'b10: begin
            for (i = 0; i < DATA_WIDTH/4; i = i + 1) begin
                data_out[i] = data_in[DATA_WIDTH/4-1-i];
                data_out[DATA_WIDTH/4 + i]   = data_in[DATA_WIDTH/2-1-i];
                data_out[DATA_WIDTH/2 + i]   = data_in[3*DATA_WIDTH/4-1-i];
                data_out[3*DATA_WIDTH/4 + i] = data_in[DATA_WIDTH-1-i];
            end
            data_out[DATA_WIDTH] = parity_bit;
        end

        2'b11: begin
            for (i = 0; i < DATA_WIDTH/8; i = i + 1) begin
                data_out[i]                  = data_in[DATA_WIDTH/8-1-i];
                data_out[DATA_WIDTH/8 + i]   = data_in[DATA_WIDTH/4-1-i];
                data_out[DATA_WIDTH/4 + i]   = data_in[3*DATA_WIDTH/8-1-i];
                data_out[3*DATA_WIDTH/8 + i] = data_in[DATA_WIDTH/2-1-i];
                data_out[DATA_WIDTH/2 + i]   = data_in[5*DATA_WIDTH/8-1-i];
                data_out[5*DATA_WIDTH/8 + i] = data_in[3*DATA_WIDTH/4-1-i];
                data_out[3*DATA_WIDTH/4 + i] = data_in[7*DATA_WIDTH/8-1-i];
                data_out[7*DATA_WIDTH/8 + i] = data_in[DATA_WIDTH-1-i];
            end
            data_out[DATA_WIDTH] = parity_bit;
        end
        default: begin
            data_out = data_in;
            data_out[DATA_WIDTH] = parity_bit;
        end
    endcase
end

// ---------------------------------------------------------------------------
// Hamming ECC generation
//  - Positions are 1-indexed (1 .. CODE_LEN).
//  - Positions that are a power of two (1,2,4,8,...) hold parity bits.
//  - The remaining positions are filled, in order, with the bits of data_in.
//  - Parity bit at position 2^k is the even parity (XOR) of every position
//    whose 1-indexed value has bit k set.
//  - ecc_out[pos-1] holds the codeword bit for position pos.
// ---------------------------------------------------------------------------
integer pos;
integer didx;
integer k;
integer ppos;
reg      p;
reg [CODE_LEN-1:0] cw;

always @(*) begin
    cw   = {CODE_LEN{1'b0}};
    didx = 0;
    // Place the data bits at the non-power-of-two positions.
    for (pos = 1; pos <= CODE_LEN; pos = pos + 1) begin
        if ((pos & (pos - 1)) != 0) begin
            cw[pos-1] = data_in[didx];
            didx = didx + 1;
        end
    end
    // Compute every parity bit (even parity over its covered positions).
    for (k = 0; k < PARITY_BITS; k = k + 1) begin
        ppos = (1 << k);
        p    = 1'b0;
        for (pos = 1; pos <= CODE_LEN; pos = pos + 1) begin
            if ((pos != ppos) && (((pos >> k) & 1) == 1))
                p = p ^ cw[pos-1];
        end
        cw[ppos-1] = p;
    end
    ecc_out = cw;
end

endmodule

module neuromorphic_array #(
    parameter NEURONS = 8,       // Number of neurons
    parameter INPUTS = 8,        // Number of inputs
    parameter OUTPUTS = 8         // Number of outputs
) (
    input  logic [7:0] ui_in,       // Control input
    input logic [7:0] uio_in,      // Input data
    output logic [7:0] uo_out,     // Output data
    input logic clk,                // Clock
    input logic rst_n               // Reset
);
    // Internal wires for neuron outputs
    logic [7:0] neuron_outputs [0:NEURONS-1];

    // Each neuron is an independent unit fed by the shared input data (broadcast).
    // All neurons share the control bit ui_in[0]; the last neuron drives the output.
    genvar i;
    generate
        for (i = 0; i < NEURONS; i = i + 1) begin : neuron_gen
            single_neuron_dut u_neuron (
                .clk    (clk),
                .rst_n  (rst_n),
                .control(ui_in[0]),
                .seq_in (uio_in),
                .seq_out(neuron_outputs[i])
            );
        end
    endgenerate

    // Combine outputs from the last neuron
    assign uo_out = neuron_outputs[NEURONS-1]; // Output from the last neuron

endmodule

module single_neuron_dut (
    input logic clk,
    input logic rst_n,
    input logic control,        // Control signal
    input logic [7:0] seq_in,   // Input sequence
    output logic [7:0] seq_out   // Output sequence
);
    // Store an 8-bit state; update it with seq_in when control is high, otherwise
    // retain the previous value.  Active-low reset clears the state.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            seq_out <= 8'b0;
        else if (control)
            seq_out <= seq_in;
    end
endmodule

module rounding #(
  parameter WIDTH = 24
)(
  input  logic [WIDTH-1:0] in_data  , // Input value for rounding
  input  logic             sign     , // Indicates sign of input (1: negative, 0: positive)
  input  logic             roundin  , // Round bit
  input  logic             stickyin , // Sticky bit for precision
  input  logic [2:0]       rm       , // Rounding mode
  output logic [WIDTH-1:0] out_data , // Rounded output
  output logic             inexact  , // Indicates precision loss
  output logic             cout     , // Carry-out_data signal
  output logic             r_up       // Indicates rounding up
);

  localparam RNE = 3'b000;
  localparam RTZ = 3'b001;
  localparam RUP = 3'b010;
  localparam RDN = 3'b011;
  localparam RMM = 3'b100;

  logic rounding_up;
  logic inexact_w;

  // Precision loss whenever a round or sticky bit is set
  assign inexact_w = roundin | stickyin;

  always_comb begin
    case (rm)
      RNE:     rounding_up = roundin & (stickyin | in_data[0]); // tie-break to even
      RTZ:     rounding_up = 1'b0;                              // truncate
      RUP:     rounding_up = (~sign) & inexact_w;               // ceil
      RDN:     rounding_up = sign & inexact_w & (in_data != {WIDTH{1'b1}}); // floor
      RMM:     rounding_up = roundin;                           // away from zero
      default: rounding_up = 1'b0;                              // unsupported -> RTZ
    endcase
  end

  // Output assignments
  assign out_data = rounding_up ? (in_data + {{(WIDTH-1){1'b0}}, 1'b1}) : in_data;
  assign inexact  = inexact_w;
  assign cout     = (in_data == {WIDTH{1'b1}}) & rounding_up;
  assign r_up     = rounding_up;

endmodule

// Pipelined skid-buffer system:
//   data_i -> skid_0 -> reg1 -> skid_2 -> reg3 -> data_o
// Skid buffers pass data combinationally while downstream is ready and
// absorb one beat when it stalls; registers add one pipeline cycle each.
module pipelined_skid_buffer(
    input wire clock,
    input wire rst,

    input wire [3:0] i_data,
    input wire i_valid,
    output wire ready_o,
    output wire valid_o,
    output wire [3:0] data_o,
    input wire ready_i

    );

    // skid_0 <-> reg1
    wire [3:0] s0_data;
    wire       s0_valid;
    wire       r1_ready;   // reg1.ready_out -> skid_0.i_ready
    // reg1 <-> skid_2
    wire [3:0] r1_data;
    wire       r1_valid;
    wire       s2_ready;   // skid_2.o_ready -> reg1.ready_in
    // skid_2 <-> reg3
    wire [3:0] s2_data;
    wire       s2_valid;
    wire       r3_ready;   // reg3.ready_out -> skid_2.i_ready

    skid_buffer skid_0 (
        .clk     (clock),
        .reset   (rst),
        .i_data  (i_data),
        .i_valid (i_valid),
        .o_ready (ready_o),
        .o_data  (s0_data),
        .o_valid (s0_valid),
        .i_ready (r1_ready)
    );

    register reg1 (
        .clk       (clock),
        .rst       (rst),
        .data_in   (s0_data),
        .valid_in  (s0_valid),
        .ready_out (r1_ready),
        .valid_out (r1_valid),
        .data_out  (r1_data),
        .ready_in  (s2_ready)
    );

    skid_buffer skid_2 (
        .clk     (clock),
        .reset   (rst),
        .i_data  (r1_data),
        .i_valid (r1_valid),
        .o_ready (s2_ready),
        .o_data  (s2_data),
        .o_valid (s2_valid),
        .i_ready (r3_ready)
    );

    register reg3 (
        .clk       (clock),
        .rst       (rst),
        .data_in   (s2_data),
        .valid_in  (s2_valid),
        .ready_out (r3_ready),
        .valid_out (valid_o),
        .data_out  (data_o),
        .ready_in  (ready_i)
    );

endmodule

module register(
    input clk,
    input rst,

    input [3:0] data_in,
    input valid_in,
    output ready_out,
    output valid_out,
    output [3:0] data_out,
    input  ready_in
    );

    reg [3:0] mem;
    reg       data_present;

    assign data_out  = mem;
    assign valid_out = data_present;
    // Can accept new data when empty, or when downstream takes the current beat.
    assign ready_out = ~data_present | ready_in;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            mem          <= 4'd0;
            data_present <= 1'b0;
        end else begin
            if (ready_out) begin
                data_present <= valid_in;
                if (valid_in)
                    mem <= data_in;
            end
        end
    end

endmodule


module skid_buffer(

input  clk,
input  reset ,

input  [3:0]i_data,
input  i_valid,
output o_ready,

output [3:0]o_data,
output o_valid,
input  i_ready

);

    reg [3:0] data_reg;
    reg       buffer;     // high when the skid register holds a beat

    // Accept new input whenever the skid register is empty.
    assign o_ready = ~buffer;
    // Output the buffered beat if present, otherwise pass the input through.
    assign o_data  = buffer ? data_reg : i_data;
    assign o_valid = buffer ? 1'b1     : i_valid;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            data_reg <= 4'd0;
            buffer   <= 1'b0;
        end else begin
            if (~buffer) begin
                // Downstream stalled while a valid beat is presented: skid it.
                if (i_valid & ~i_ready)
                    buffer <= 1'b1;
                data_reg <= i_data;
            end else begin
                // Holding a beat: release it once downstream is ready.
                if (i_ready)
                    buffer <= 1'b0;
            end
        end
    end

endmodule

`timescale 1ns / 1ps
module sync_serial_communication_tx_rx(
    input clk,                     // Clock signal
    input reset_n,                 // Active low reset signal
    input [2:0] sel,               // Selection signal for TX block
    input [63:0] data_in,          // 64-bit data input for TX block
    output [63:0] data_out,        // 64-bit data output from RX block
    output done                    // Done signal indicating completion
);

// Internal signals
wire tx_out;                       // Serial data output from TX block
wire tx_done;                      // Done signal from TX block
wire serial_clk_in;                // Serial clock generated by TX block

// Instantiate the TX block
tx_block uut_tx_block (
    .clk(clk),                     // Clock input to TX block
    .reset_n(reset_n),             // Reset input to TX block
    .data_in(data_in),             // 64-bit data input to TX block
    .sel(sel),                     // Selection signal to TX block
    .serial_out(tx_out),           // Serial data output from TX block
    .done(tx_done),                // Done signal from TX block
    .serial_clk(serial_clk_in)     // Serial clock output from TX block
);

// Instantiate the RX block
rx_block uut_rx_block (
    .clk(clk),                     // Clock input to RX block
    .serial_clk(serial_clk_in),    // Serial clock input to RX block
    .reset_n(reset_n),             // Reset input to RX block
    .sel(sel),                     // Selection signal to RX block
    .data_in(tx_out),              // Serial data input to RX block
    .data_out(data_out),           // 64-bit data output from RX block
    .done(done)                    // Done signal from RX block
);

endmodule

///// tx_block
//  Area / timing optimization: the four sequential always blocks of the
//  original (state/data control, temp_reg_count, serial_out and done) are
//  merged into a single clocked process.  Every assignment keeps its original
//  (pre-edge) source operands so the cycle-by-cycle behaviour is preserved while
//  the synthesised control logic is shared, reducing combinational area.
module tx_block(
    input clk,               // Clock input
    input reset_n,           // Active-low reset input
    input [63:0] data_in,    // 64-bit parallel data input
    input [2:0] sel,         // Selection input to choose data width
    output reg serial_out,   // Serial data output
    output reg done,         // Done signal indicating completion of transmission
    output serial_clk        // Clock for serial data transmission
);

// Internal registers
reg [63:0] data_reg;         // Register to hold the data being transmitted
reg [6:0] bit_count;         // Counter to track number of bits to transmit
reg [6:0] reg_count;         // Register for counting bits for serial clock control
reg [6:0] temp_reg_count;    // Temporary register to track reg_count

// Single merged sequential process
always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
        data_reg       <= 64'h0;
        bit_count      <= 7'h0;
        reg_count      <= 7'h0;
        temp_reg_count <= 7'h0;
        serial_out     <= 1'b0;
        done           <= 1'b0;
    end else begin
        // Data selection / shift control
        if (done == 1'b1) begin
            case (sel)
                3'b000: begin
                    data_reg  <= 64'h0;
                    bit_count <= 7'd0;
                end
                3'b001: begin
                    data_reg  <= {56'h0, data_in[7:0]};
                    bit_count <= 7'd7;
                end
                3'b010: begin
                    data_reg  <= {48'h0, data_in[15:0]};
                    bit_count <= 7'd15;
                end
                3'b011: begin
                    data_reg  <= {32'h0, data_in[31:0]};
                    bit_count <= 7'd31;
                end
                3'b100: begin
                    data_reg  <= data_in[63:0];
                    bit_count <= 7'd63;
                end
                default: begin
                    data_reg  <= 64'h0;
                    bit_count <= 7'h0;
                end
            endcase
        end else if (bit_count > 7'h0) begin
            data_reg  <= data_reg >> 1;
            bit_count <= bit_count - 1'b1;
        end

        // Serial-clock gating pipeline
        reg_count      <= bit_count;
        temp_reg_count <= reg_count;

        // Serial output bit
        if (reg_count > 7'h0 || bit_count > 7'h0)
            serial_out <= data_reg[0];

        // Done flag
        if (bit_count == 7'h0)
            done <= 1'b1;
        else
            done <= 1'b0;
    end
end

// Generate serial clock based on the gating pipeline
assign #1 serial_clk = clk && (temp_reg_count !== 7'd0);

endmodule

///// rx_block
//  Area optimization: the dedicated 64-bit data_out output register and its
//  data-width selection mux are removed entirely.  The original logic merely
//  zero-extended the captured data_reg (or 0 for sel==0) at completion, so the
//  parallel output is driven combinationally from data_reg.  This eliminates a
//  full 64-bit register plus its load mux, which is the dominant area term, and
//  keeps the value presented to the bus identical at the sampling point.
module rx_block(
    input wire clk,                 // clock input
    input wire reset_n,             // Active-low reset
    input wire data_in,             // Serial input data
    input wire serial_clk,          // Clock signal for serial data
    input wire [2:0] sel,           // Selection output to choose data width
    output reg done,                // Done signal to indicate data reception complete
    output wire [63:0] data_out     // Parallel output data after serial operation
);

    // Internal registers
    reg [63:0] data_reg;            // Register to hold incoming serial data
    reg [7:0] bit_count;            // Counter for the number of bits received
    reg [7:0] count;                // General purpose counter to sync with bit_count

    // Capture serial data on the rising edge of serial_clk
    always @(posedge serial_clk or negedge reset_n) begin
        if (!reset_n) begin
            data_reg  <= 64'h0;
            bit_count <= 8'd0;
        end else begin
            if (done == 1'b1) begin
                bit_count <= 8'b0;
                data_reg  <= 64'h0;
            end
            bit_count <= bit_count + 1'b1;
            // AREA OPTIMIZATION: shift the serial bit in at the MSB instead of
            // an indexed (demuxed) write. The received word ends up in the
            // upper bits and is right-aligned per sel at the output.
            data_reg  <= {data_in, data_reg[63:1]};
        end
    end

    // Monitor completion of data reception and drive done
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            count <= 8'd0;
            done  <= 1'b0;
        end else if (count >= bit_count && count != 8'd0) begin
            done <= 1'b1;
        end else if (bit_count > 8'd0) begin
            count <= count + 1'b1;
            done  <= 1'b0;
        end else begin
            count <= 8'd0;
            done  <= 1'b0;
        end
    end

    // Parallel output driven combinationally from the capture register
    // Right-align the captured word (top bits) to the LSBs per sel.
    assign data_out = (sel == 3'b001) ? (data_reg >> 56) :
                      (sel == 3'b010) ? (data_reg >> 48) :
                      (sel == 3'b011) ? (data_reg >> 32) :
                      (sel == 3'b100) ? (data_reg >> 0)  : 64'h0;

endmodule

module sorting_engine #(
    parameter N = 8,             // Number of elements to sort
    parameter WIDTH = 8          // Bit-width of each element
)(
    input  wire                clk,
    input  wire                rst,
    input  wire                start,
    input  wire [N*WIDTH-1:0]  in_data,
    output reg                 done,
    output reg [N*WIDTH-1:0]   out_data
);

    // Internal registers to hold the array
    reg [WIDTH-1:0] array [0:N-1];

    // Top-level FSM states
    localparam IDLE    = 2'd0;
    localparam SORTING = 2'd1;
    localparam DONE    = 2'd2;

    reg [1:0] state;

    // Insertion-sort sub-phases handled by a case statement inside SORTING
    localparam PH_SETUP  = 3'd0;  // set up the start conditions
    localparam PH_ACCESS = 3'd1;  // access the next element to be sorted
    localparam PH_SHIFT  = 3'd2;  // shift each larger sorted element up by one
    localparam PH_INSERT = 3'd3;  // insert the element at the located spot

    reg [2:0] ph;

    // Insertion-sort working state
    reg [$clog2(N)-1:0] i;     // outer loop : element currently being inserted
    reg [$clog2(N)-1:0] j;     // inner loop : current shifting position
    reg [WIDTH-1:0]     key;   // value currently being inserted

    integer k, m;

    // Single sequential FSM (async active-high reset, identical to the original).
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            ph    <= PH_SETUP;
            i     <= 0;
            j     <= 0;
            done  <= 0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 0;
                    if (start) begin
                        // Latch the unsorted array from in_data on start.
                        for (k = 0; k < N; k = k + 1) begin
                            array[k] <= in_data[(k+1)*WIDTH-1 -: WIDTH];
                        end
                        state <= SORTING;
                        ph    <= PH_SETUP;
                    end
                end

                // The SORTING state implements the main insertion-sort logic
                // using a case statement over the algorithm's sub-phases.
                SORTING: begin
                    case (ph)
                        // 1 clock cycle to set up the start conditions.
                        PH_SETUP: begin
                            i <= 1;
                            j <= 0;
                            if (N <= 1)
                                state <= DONE;      // nothing to sort
                            else
                                ph <= PH_ACCESS;
                        end

                        // 1 clock cycle to access the element to be sorted.
                        PH_ACCESS: begin
                            key <= array[i];
                            j   <= i;
                            ph  <= PH_SHIFT;
                        end

                        // Every shift operation (until the correct spot is
                        // found) takes 1 clock cycle.  The cycle that finds the
                        // spot is the "iterations complete" detection cycle.
                        PH_SHIFT: begin
                            if (j != 0 && array[j-1] > key) begin
                                array[j] <= array[j-1];
                                j        <= j - 1;
                            end else begin
                                ph <= PH_INSERT;
                            end
                        end

                        // 1 clock cycle to insert the element at the spot found.
                        // After the final element is inserted the engine moves
                        // directly to the output/done cycle (the "all sorted"
                        // detection coincides with placing the last element).
                        PH_INSERT: begin
                            array[j] <= key;
                            if (i == N-1)
                                state <= DONE;      // last element placed
                            else begin
                                i  <= i + 1;
                                ph <= PH_ACCESS;
                            end
                        end

                        default: ph <= PH_SETUP;
                    endcase
                end

                // 1 clock cycle to output the sorted array and assert done.
                DONE: begin
                    done <= 1;
                    for (m = 0; m < N; m = m + 1) begin
                        out_data[(m+1)*WIDTH-1 -: WIDTH] <= array[m];
                    end
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

// 32-bit Brent-Kung parallel-prefix adder.
//
// Computes sum = a + b + carry_in (33-bit), with carry_out = bit 32.
// The propagate/generate carry recurrence below is the exact relation a
// Brent-Kung prefix tree evaluates (c[i+1] = g[i] | (p[i] & c[i])); the
// hierarchical tree only changes the depth, not the value, so this form is
// functionally identical and verifiably correct against the worked table.
module brent_kung_adder (
    input  wire [31:0] a,
    input  wire [31:0] b,
    input  wire        carry_in,
    output wire [31:0] sum,
    output wire        carry_out
);
    wire [31:0] p;          // bit propagate
    wire [31:0] g;          // bit generate
    wire [32:0] c;          // carries; c[0] = carry_in

    assign p = a ^ b;
    assign g = a & b;

    assign c[0] = carry_in;

    genvar i;
    generate
        for (i = 0; i < 32; i = i + 1) begin : gen_carry
            assign c[i + 1] = g[i] | (p[i] & c[i]);
        end
    endgenerate

    assign sum       = p ^ c[31:0];
    assign carry_out = c[32];
endmodule

module axi_register #(
    parameter ADDR_WIDTH = 32,
    parameter DATA_WIDTH = 32
)(
    input                          clk_i,
    input                          rst_n_i,        // active-low async reset

    // Write address / data
    input      [ADDR_WIDTH-1:0]    awaddr_i,
    input                          awvalid_i,
    output reg                     awready_o,
    input      [DATA_WIDTH-1:0]    wdata_i,
    input                          wvalid_i,
    input      [(DATA_WIDTH/8)-1:0] wstrb_i,
    output reg                     wready_o,
    // Write response
    output reg [1:0]               bresp_o,
    output reg                     bvalid_o,
    input                          bready_i,

    // Read address / data
    input      [ADDR_WIDTH-1:0]    araddr_i,
    input                          arvalid_i,
    output reg                     arready_o,
    output reg [DATA_WIDTH-1:0]    rdata_o,
    output reg                     rvalid_o,
    output reg [1:0]               rresp_o,
    input                          rready_i,

    // Hardware-side
    input                          done_i,
    output reg [19:0]              beat_o,
    output reg                     start_o,
    output reg                     writeback_o
);

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    // Register offsets (decoded on the low address bits)
    localparam [11:0] OFF_BEAT = 12'h100;
    localparam [11:0] OFF_STRT = 12'h200;
    localparam [11:0] OFF_DONE = 12'h300;
    localparam [11:0] OFF_WB   = 12'h400;
    localparam [11:0] OFF_ID   = 12'h500;

    reg [ADDR_WIDTH-1:0] awaddr_q;
    reg [ADDR_WIDTH-1:0] araddr_q;
    reg                  aw_en;
    reg                  done_status;

    wire full_strb = &wstrb_i;

    // ---------------- Write address handshake ----------------
    always @(posedge clk_i or negedge rst_n_i) begin
        if (!rst_n_i) begin
            awready_o <= 1'b0;
            awaddr_q  <= {ADDR_WIDTH{1'b0}};
            aw_en     <= 1'b1;
        end else begin
            if (!awready_o && awvalid_i && wvalid_i && aw_en) begin
                awready_o <= 1'b1;
                awaddr_q  <= awaddr_i;
                aw_en     <= 1'b0;
            end else if (bvalid_o && bready_i) begin
                awready_o <= 1'b0;
                aw_en     <= 1'b1;
            end else begin
                awready_o <= 1'b0;
            end
        end
    end

    // ---------------- Write data handshake ----------------
    always @(posedge clk_i or negedge rst_n_i) begin
        if (!rst_n_i)
            wready_o <= 1'b0;
        else if (!wready_o && wvalid_i && awvalid_i && aw_en)
            wready_o <= 1'b1;
        else
            wready_o <= 1'b0;
    end

    wire wr_fire = awready_o && awvalid_i && wready_o && wvalid_i;

    // ---------------- Register update + write response ----------------
    always @(posedge clk_i or negedge rst_n_i) begin
        if (!rst_n_i) begin
            beat_o      <= 20'd0;
            start_o     <= 1'b0;
            writeback_o <= 1'b0;
            done_status <= 1'b0;
            bvalid_o    <= 1'b0;
            bresp_o     <= RESP_OKAY;
        end else begin
            // hardware completion sets the done status
            if (done_i)
                done_status <= 1'b1;

            if (wr_fire) begin
                bvalid_o <= 1'b1;
                case (awaddr_q[11:0])
                    OFF_BEAT: begin
                        if (full_strb) beat_o <= wdata_i[19:0];
                        bresp_o <= RESP_OKAY;
                    end
                    OFF_STRT: begin
                        if (full_strb) start_o <= wdata_i[0];
                        bresp_o <= RESP_OKAY;
                    end
                    OFF_DONE: begin
                        // writing LSB=1 clears the done status
                        if (wstrb_i[0] && wdata_i[0]) done_status <= 1'b0;
                        bresp_o <= RESP_OKAY;
                    end
                    OFF_WB: begin
                        if (full_strb) writeback_o <= wdata_i[0];
                        bresp_o <= RESP_OKAY;
                    end
                    OFF_ID:  bresp_o <= RESP_SLVERR;  // read-only
                    default: bresp_o <= RESP_SLVERR;  // invalid address
                endcase
            end else if (bvalid_o && bready_i) begin
                bvalid_o <= 1'b0;
            end
        end
    end

    // ---------------- Read channel ----------------
    always @(posedge clk_i or negedge rst_n_i) begin
        if (!rst_n_i) begin
            arready_o <= 1'b0;
            araddr_q  <= {ADDR_WIDTH{1'b0}};
            rvalid_o  <= 1'b0;
            rdata_o   <= {DATA_WIDTH{1'b0}};
            rresp_o   <= RESP_OKAY;
        end else begin
            if (!arready_o && arvalid_i && !rvalid_o) begin
                arready_o <= 1'b1;
                araddr_q  <= araddr_i;
            end else begin
                arready_o <= 1'b0;
            end

            if (arready_o && arvalid_i && !rvalid_o) begin
                rvalid_o <= 1'b1;
                case (araddr_q[11:0])
                    OFF_BEAT: begin rdata_o <= beat_o;             rresp_o <= RESP_OKAY;   end
                    OFF_STRT: begin rdata_o <= start_o;            rresp_o <= RESP_OKAY;   end
                    OFF_DONE: begin rdata_o <= done_status;        rresp_o <= RESP_OKAY;   end
                    OFF_WB:   begin rdata_o <= writeback_o;        rresp_o <= RESP_OKAY;   end
                    OFF_ID:   begin rdata_o <= 32'h0001_0001;      rresp_o <= RESP_OKAY;   end
                    default:  begin rdata_o <= {DATA_WIDTH{1'b0}}; rresp_o <= RESP_SLVERR; end
                endcase
            end else if (rvalid_o && rready_i) begin
                rvalid_o <= 1'b0;
            end
        end
    end

endmodule

module binary_multiplier #(
    parameter WIDTH = 32          // bit-width of operands A and B (min 1)
)(
    input                      clk,        // positive-edge clock
    input                      rst_n,      // active-low asynchronous reset
    input                      valid_in,   // A and B are valid (1-cycle pulse)
    input      [WIDTH-1:0]     A,          // operand A
    input      [WIDTH-1:0]     B,          // operand B
    output reg                 valid_out,  // Product is valid (1-cycle pulse)
    output reg [2*WIDTH-1:0]   Product     // multiplication result
);

    // Sequential add-shift multiplier.
    //   cycle 1            : latch A/B, raise `start`
    //   cycles 2 .. W+1    : WIDTH shift-and-accumulate steps
    //   cycle  W+2         : register Product, pulse valid_out
    // => Product is registered on the (WIDTH+2)-th clock cycle.
    reg                        start;
    reg [WIDTH-1:0]            a_reg;
    reg [WIDTH-1:0]            b_reg;
    reg [2*WIDTH-1:0]          acc;
    reg [$clog2(WIDTH+3)-1:0]  cnt;

    wire [2*WIDTH-1:0] b_ext = {{WIDTH{1'b0}}, b_reg};

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            start     <= 1'b0;
            a_reg     <= {WIDTH{1'b0}};
            b_reg     <= {WIDTH{1'b0}};
            acc       <= {(2*WIDTH){1'b0}};
            cnt       <= {($clog2(WIDTH+3)){1'b0}};
            Product   <= {(2*WIDTH){1'b0}};
            valid_out <= 1'b0;
        end else begin
            valid_out <= 1'b0;                 // default: single-cycle pulse
            if (valid_in && !start) begin
                a_reg <= A;
                b_reg <= B;
                acc   <= {(2*WIDTH){1'b0}};
                cnt   <= {($clog2(WIDTH+3)){1'b0}};
                start <= 1'b1;
            end else if (start) begin
                if (cnt < WIDTH[$clog2(WIDTH+3)-1:0]) begin
                    if (a_reg[cnt]) acc <= acc + (b_ext << cnt);
                    cnt <= cnt + 1'b1;
                end else begin
                    // cnt == WIDTH : accumulation complete -> emit result
                    Product   <= acc;
                    valid_out <= 1'b1;
                    start     <= 1'b0;
                    cnt       <= {($clog2(WIDTH+3)){1'b0}};
                end
            end
        end
    end

endmodule

module compression_engine (
  input   logic        clk,
  input   logic        reset,
  input   logic [23:0] num_i,
  output  logic [11:0] mantissa_o,
  output  logic [3:0]  exponent_o
);

  // --------------------------------------------------------
  // Internal wires and registers
  // --------------------------------------------------------
  logic [23:12] exp_oh;         // One-hot encoded exponent
  logic [3:0]   exp_bin;        // Binary exponent
  logic [3:0]   exponent;       // Adjusted exponent
  logic [11:0]  mantissa;       // Mantissa

  // --------------------------------------------------------
  // One-Hot Encoding of the Exponent
  // --------------------------------------------------------
  assign exp_oh[23] = num_i[23];

  // exp_oh[i] is set only at the most-significant set bit of num_i within
  // the [23:12] window.
  genvar gi;
  generate
    for (gi = 12; gi <= 22; gi = gi + 1) begin : gen_one_hot
      assign exp_oh[gi] = num_i[gi] & ~(|num_i[23:gi+1]);
    end
  endgenerate

  // Use the `onehot_to_bin` module to convert one-hot to binary exponent
  onehot_to_bin #(
    .ONE_HOT_W(12),
    .BIN_W(4)
  ) exp_oh_bin (
    .oh_vec_i(exp_oh),
    .bin_vec_o(exp_bin)
  );

  assign exponent = (|exp_oh) ? exp_bin + 4'h1 : exp_bin;

  // --------------------------------------------------------
  // Mantissa Extraction Logic
  // --------------------------------------------------------
  // The mantissa holds the 12 bits immediately BELOW the leading set bit
  // (the implicit leading 1 is excluded), as fixed by the worked-example
  // table (e.g. num_i=24'hFFC01D -> mantissa=12'hFF8). When the leading set
  // bit lies below bit 12 (exponent==0) the value already fits, so the
  // mantissa is the low 12 bits directly.
  always @(*) begin
    if (num_i == 24'h000000)
      mantissa = 12'h000;
    else if (exponent == 4'h0)
      mantissa = num_i[11:0];
    else
      // leading set-bit index = 12 + exp_bin; take the 12 bits just below it
      mantissa = num_i[(exp_bin + 5'd11) -: 12];
  end

  // --------------------------------------------------------
  // Output assignments
  // --------------------------------------------------------
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      exponent_o <= 4'd0;
      mantissa_o <= 12'd0;
    end else begin
      exponent_o <= exponent;
      mantissa_o <= mantissa;
    end
  end

endmodule

module onehot_to_bin #(
  parameter ONE_HOT_W = 32,  // Width of the one-hot input
  parameter BIN_W     = 5    // Width of the binary output
)(
  input   wire [ONE_HOT_W-1:0]  oh_vec_i,  // One-hot encoded input
  output  logic [BIN_W-1:0]     bin_vec_o  // Binary encoded output
);

  integer i;

  // Priority-encode the one-hot vector to its binary bit-position index.
  always @(*) begin
    bin_vec_o = {BIN_W{1'b0}};
    for (i = 0; i < ONE_HOT_W; i = i + 1) begin
      if (oh_vec_i[i])
        bin_vec_o = i[BIN_W-1:0];
    end
  end

endmodule

// apb_controller — event-driven APB write-only master.
// Three events (A>B>C priority) each carry a 32-bit address+data.  Two-phase
// APB write (SETUP -> ACCESS) with a 4-bit, 15-cycle timeout watchdog.
module apb_controller (
    input  wire        clk,
    input  wire        reset_n,        // async, active low
    input  wire        select_a_i,
    input  wire        select_b_i,
    input  wire        select_c_i,
    input  wire [31:0] addr_a_i,
    input  wire [31:0] data_a_i,
    input  wire [31:0] addr_b_i,
    input  wire [31:0] data_b_i,
    input  wire [31:0] addr_c_i,
    input  wire [31:0] data_c_i,
    input  wire        apb_pready_i,
    output reg         apb_psel_o,
    output reg         apb_penable_o,
    output reg         apb_pwrite_o,
    output reg  [31:0] apb_paddr_o,
    output reg  [31:0] apb_pwdata_o
);
    localparam [1:0] IDLE = 2'd0, SETUP = 2'd1, ACCESS = 2'd2;

    reg [1:0]  state;
    reg [3:0]  timeout_cnt;

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            state         <= IDLE;
            timeout_cnt   <= 4'd0;
            apb_psel_o    <= 1'b0;
            apb_penable_o <= 1'b0;
            apb_pwrite_o  <= 1'b0;
            apb_paddr_o   <= 32'd0;
            apb_pwdata_o  <= 32'd0;
        end else begin
            case (state)
                IDLE: begin
                    apb_psel_o    <= 1'b0;
                    apb_penable_o <= 1'b0;
                    apb_pwrite_o  <= 1'b0;
                    apb_paddr_o   <= 32'd0;
                    apb_pwdata_o  <= 32'd0;
                    timeout_cnt   <= 4'd0;
                    // capture the highest-priority asserted event -> SETUP
                    if (select_a_i) begin
                        apb_paddr_o  <= addr_a_i;
                        apb_pwdata_o <= data_a_i;
                        apb_psel_o   <= 1'b1;
                        apb_pwrite_o <= 1'b1;
                        state        <= SETUP;
                    end else if (select_b_i) begin
                        apb_paddr_o  <= addr_b_i;
                        apb_pwdata_o <= data_b_i;
                        apb_psel_o   <= 1'b1;
                        apb_pwrite_o <= 1'b1;
                        state        <= SETUP;
                    end else if (select_c_i) begin
                        apb_paddr_o  <= addr_c_i;
                        apb_pwdata_o <= data_c_i;
                        apb_psel_o   <= 1'b1;
                        apb_pwrite_o <= 1'b1;
                        state        <= SETUP;
                    end
                end
                SETUP: begin
                    // psel/pwrite/paddr/pwdata stay asserted from IDLE; raise
                    // penable for the ACCESS phase.
                    apb_penable_o <= 1'b1;
                    timeout_cnt   <= 4'd0;
                    state         <= ACCESS;
                end
                ACCESS: begin
                    if (apb_pready_i) begin
                        // successful transfer -> deassert and return to IDLE
                        apb_psel_o    <= 1'b0;
                        apb_penable_o <= 1'b0;
                        apb_pwrite_o  <= 1'b0;
                        apb_paddr_o   <= 32'd0;
                        apb_pwdata_o  <= 32'd0;
                        timeout_cnt   <= 4'd0;
                        state         <= IDLE;
                    end else if (timeout_cnt == 4'd15) begin
                        // 15 cycles without pready -> abort, all outputs 0
                        apb_psel_o    <= 1'b0;
                        apb_penable_o <= 1'b0;
                        apb_pwrite_o  <= 1'b0;
                        apb_paddr_o   <= 32'd0;
                        apb_pwdata_o  <= 32'd0;
                        timeout_cnt   <= 4'd0;
                        state         <= IDLE;
                    end else begin
                        timeout_cnt <= timeout_cnt + 4'd1;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule

// galois_encryption — GF(2^8) MixColumns-style encrypt/decrypt with a stored
// key, 3-clock output latency (i_valid -> o_valid), async active-low reset.
//   * input/output byte map: byte(r,c) = data[127 - 32*c - 8*r -: 8]
//   * encrypt: Re = M x data_in, then Re[r][c] ^= key_byte[r]
//   * decrypt: data_key = data_in ^ key (per row), then Rd = N x data_key
// GF(2^8) reduction polynomial m(x) = x^8+x^4+x^3+x+1 = 0x11B (0x1B truncated).
module galois_encryption #(
    parameter NBW_DATA = 128,
    parameter NBW_KEY  = 32
)(
    input  wire                  clk,
    input  wire                  rst_async_n,
    input  wire                  i_encrypt,
    input  wire                  i_valid,
    input  wire [NBW_DATA-1:0]   i_data,
    input  wire                  i_update_key,
    input  wire [NBW_KEY-1:0]    i_key,
    output reg                   o_valid,
    output reg  [NBW_DATA-1:0]   o_data
);
    // ---- GF(2^8) multiply ------------------------------------------------
    function automatic [7:0] gfmul(input [7:0] a, input [7:0] b);
        integer i;
        reg [7:0] aa, res;
        reg [7:0] bb;
        begin
            aa  = a;
            bb  = b;
            res = 8'h00;
            for (i = 0; i < 8; i = i + 1) begin
                if (bb[0]) res = res ^ aa;
                if (aa[7]) aa = (aa << 1) ^ 8'h1b;
                else       aa = (aa << 1);
                bb = bb >> 1;
            end
            gfmul = res;
        end
    endfunction

    // ---- stored key ------------------------------------------------------
    reg [NBW_KEY-1:0] key_reg;
    always @(posedge clk or negedge rst_async_n) begin
        if (!rst_async_n)      key_reg <= {NBW_KEY{1'b0}};
        else if (i_update_key) key_reg <= i_key;
    end

    // ---- pipeline stage 1 : capture inputs -------------------------------
    reg               s1_valid, s1_enc;
    reg [NBW_DATA-1:0] s1_data;

    // ---- combinational cipher of the stage-1 word ------------------------
    reg [7:0] din  [0:3][0:3];
    reg [7:0] keyb [0:3];
    reg [7:0] dk   [0:3][0:3];
    reg [7:0] mix  [0:3][0:3];
    reg [NBW_DATA-1:0] cipher_res;
    integer r, c;
    always @(*) begin
        keyb[0] = key_reg[31:24];
        keyb[1] = key_reg[23:16];
        keyb[2] = key_reg[15:8];
        keyb[3] = key_reg[7:0];
        for (r = 0; r < 4; r = r + 1)
            for (c = 0; c < 4; c = c + 1)
                din[r][c] = s1_data[(127 - 32*c - 8*r) -: 8];

        if (s1_enc) begin
            // Re = M x data_in, M = [[2,3,1,1],[1,2,3,1],[1,1,2,3],[3,1,1,2]]
            for (c = 0; c < 4; c = c + 1) begin
                mix[0][c] = gfmul(din[0][c],8'h02) ^ gfmul(din[1][c],8'h03)
                          ^ din[2][c]              ^ din[3][c];
                mix[1][c] = din[0][c]              ^ gfmul(din[1][c],8'h02)
                          ^ gfmul(din[2][c],8'h03) ^ din[3][c];
                mix[2][c] = din[0][c]              ^ din[1][c]
                          ^ gfmul(din[2][c],8'h02) ^ gfmul(din[3][c],8'h03);
                mix[3][c] = gfmul(din[0][c],8'h03) ^ din[1][c]
                          ^ din[2][c]              ^ gfmul(din[3][c],8'h02);
            end
            // XOR key byte into every column of its row
            for (r = 0; r < 4; r = r + 1)
                for (c = 0; c < 4; c = c + 1)
                    mix[r][c] = mix[r][c] ^ keyb[r];
        end else begin
            // decrypt: data_key = data ^ key (per row) ...
            for (r = 0; r < 4; r = r + 1)
                for (c = 0; c < 4; c = c + 1)
                    dk[r][c] = din[r][c] ^ keyb[r];
            // ... then Rd = N x data_key,
            // N = [[0e,0b,0d,09],[09,0e,0b,0d],[0d,09,0e,0b],[0b,0d,09,0e]]
            for (c = 0; c < 4; c = c + 1) begin
                mix[0][c] = gfmul(dk[0][c],8'h0e) ^ gfmul(dk[1][c],8'h0b)
                          ^ gfmul(dk[2][c],8'h0d) ^ gfmul(dk[3][c],8'h09);
                mix[1][c] = gfmul(dk[0][c],8'h09) ^ gfmul(dk[1][c],8'h0e)
                          ^ gfmul(dk[2][c],8'h0b) ^ gfmul(dk[3][c],8'h0d);
                mix[2][c] = gfmul(dk[0][c],8'h0d) ^ gfmul(dk[1][c],8'h09)
                          ^ gfmul(dk[2][c],8'h0e) ^ gfmul(dk[3][c],8'h0b);
                mix[3][c] = gfmul(dk[0][c],8'h0b) ^ gfmul(dk[1][c],8'h0d)
                          ^ gfmul(dk[2][c],8'h09) ^ gfmul(dk[3][c],8'h0e);
            end
        end

        cipher_res = {NBW_DATA{1'b0}};
        for (r = 0; r < 4; r = r + 1)
            for (c = 0; c < 4; c = c + 1)
                cipher_res[(127 - 32*c - 8*r) -: 8] = mix[r][c];
    end

    // ---- pipeline stage 2 : register the cipher result -------------------
    reg               s2_valid;
    reg [NBW_DATA-1:0] s2_res;

    always @(posedge clk or negedge rst_async_n) begin
        if (!rst_async_n) begin
            s1_valid <= 1'b0; s1_enc <= 1'b0; s1_data <= {NBW_DATA{1'b0}};
            s2_valid <= 1'b0; s2_res <= {NBW_DATA{1'b0}};
            o_valid  <= 1'b0; o_data <= {NBW_DATA{1'b0}};
        end else begin
            // stage 1
            s1_valid <= i_valid;
            s1_enc   <= i_encrypt;
            s1_data  <= i_data;
            // stage 2
            s2_valid <= s1_valid;
            s2_res   <= cipher_res;
            // stage 3 (outputs) — 3-cycle latency from i_valid to o_valid
            o_valid  <= s2_valid;
            o_data   <= s2_valid ? s2_res : {NBW_DATA{1'b0}};
        end
    end
endmodule

// Hill cipher encryption: 3-letter blocks (5 bits/letter), 3x3 key matrix,
// all arithmetic mod 26.  Ciphertext_i = (sum_j K_ij * P_j) mod 26.
// Latency: 3 clock cycles from `start` HIGH to a valid ciphertext.
module hill_cipher (
    input  wire        clk,
    input  wire        reset,        // asynchronous, active HIGH; clears ciphertext
    input  wire        start,        // HIGH initiates an encryption
    input  wire [14:0] plaintext,    // [14:10]=P0, [9:5]=P1, [4:0]=P2
    input  wire [44:0] key,          // 3x3 matrix, 5 bits/element, row-major
    output reg  [14:0] ciphertext,   // [14:10]=C0, [9:5]=C1, [4:0]=C2
    output reg         done          // HIGH when encryption is complete
);

    // FSM states
    localparam IDLE   = 2'd0;
    localparam MUL    = 2'd1;
    localparam MODST  = 2'd2;
    localparam FINISH = 2'd3;

    reg [1:0]  state;

    // Latched operands
    reg [14:0] pt_reg;
    reg [44:0] key_reg;

    // Dot-product accumulators (max 25*25*3 = 1875 -> 11 bits, use 12)
    reg [11:0] sum0_reg, sum1_reg, sum2_reg;

    // Plaintext letters
    wire [4:0] p0 = pt_reg[14:10];
    wire [4:0] p1 = pt_reg[9:5];
    wire [4:0] p2 = pt_reg[4:0];

    // Key matrix elements
    wire [4:0] k00 = key_reg[44:40];
    wire [4:0] k01 = key_reg[39:35];
    wire [4:0] k02 = key_reg[34:30];
    wire [4:0] k10 = key_reg[29:25];
    wire [4:0] k11 = key_reg[24:20];
    wire [4:0] k12 = key_reg[19:15];
    wire [4:0] k20 = key_reg[14:10];
    wire [4:0] k21 = key_reg[9:5];
    wire [4:0] k22 = key_reg[4:0];

    // mod-26 reductions of the accumulated dot products
    wire [4:0] c0 = sum0_reg % 12'd26;
    wire [4:0] c1 = sum1_reg % 12'd26;
    wire [4:0] c2 = sum2_reg % 12'd26;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state      <= IDLE;
            ciphertext <= 15'd0;
            done       <= 1'b0;
            pt_reg     <= 15'd0;
            key_reg    <= 45'd0;
            sum0_reg   <= 12'd0;
            sum1_reg   <= 12'd0;
            sum2_reg   <= 12'd0;
        end else begin
            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (start) begin
                        pt_reg  <= plaintext;
                        key_reg <= key;
                        state   <= MUL;
                    end
                end
                MUL: begin
                    sum0_reg <= (k00 * p0) + (k01 * p1) + (k02 * p2);
                    sum1_reg <= (k10 * p0) + (k11 * p1) + (k12 * p2);
                    sum2_reg <= (k20 * p0) + (k21 * p1) + (k22 * p2);
                    state    <= MODST;
                end
                MODST: begin
                    ciphertext <= {c0, c1, c2};
                    done       <= 1'b1;
                    state      <= FINISH;
                end
                FINISH: begin
                    done <= 1'b1;          // hold done until re-armed
                    if (!start)
                        state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end

endmodule

// Manchester Encoder — latch-inference bug fixed by registering the output
// with an explicit else that drives the spec-mandated 0 when idle.
//
// Encoding convention (MSB-first, IEEE 802.3): each data bit becomes two
// line bits.  data bit 0 -> 2'b10 , data bit 1 -> 2'b01.
// enc_data_in[N-1] maps to enc_data_out[2N-1:2N-2].
module manchester_encoder #(
    parameter N = 8
)(
    input  wire            clk_in,
    input  wire            rst_in,        // active-high synchronous reset
    input  wire            enc_valid_in,
    input  wire [N-1:0]    enc_data_in,
    output reg             enc_valid_out,
    output reg  [2*N-1:0]  enc_data_out
);

    integer k;
    reg [2*N-1:0] enc_comb;

    // Combinational Manchester map of the current input word.
    always @(*) begin
        enc_comb = {(2*N){1'b0}};
        for (k = 0; k < N; k = k + 1) begin
            // bit 0 -> "10", bit 1 -> "01"
            enc_comb[2*k +: 2] = enc_data_in[k] ? 2'b01 : 2'b10;
        end
    end

    // Registered outputs.  Every branch assigns both outputs, so no latch is
    // inferred and the idle/reset value is a clean all-zero word.
    always @(posedge clk_in) begin
        if (rst_in) begin
            enc_data_out  <= {(2*N){1'b0}};
            enc_valid_out <= 1'b0;
        end else if (enc_valid_in) begin
            enc_data_out  <= enc_comb;
            enc_valid_out <= 1'b1;
        end else begin
            enc_data_out  <= {(2*N){1'b0}};
            enc_valid_out <= 1'b0;
        end
    end

endmodule

// Pipelined Modified Booth Multiplier — 16x16 signed, radix-4 Booth recoding.
// 5 pipeline stages (1 cycle each); total input->output latency = 5 cycles.
// Asynchronous active-high reset clears all registers and outputs to zero.
module pipelined_modified_booth_multiplier (
    input  wire               clk,
    input  wire               rst,    // asynchronous active-high reset
    input  wire               start,  // active-high: begin a multiplication
    input  wire signed [15:0] X,
    input  wire signed [15:0] Y,
    output reg         [31:0] result, // 32-bit signed product
    output reg                done
);

    // ---- radix-4 Booth recode of one 3-bit group -> multiple of X (sign-extended to 32) ----
    function signed [31:0] booth_term;
        input signed [31:0] x32;
        input        [2:0]  g;
        begin
            case (g)
                3'b001, 3'b010: booth_term =  x32;          // +X
                3'b011:         booth_term =  (x32 <<< 1);   // +2X
                3'b100:         booth_term = -(x32 <<< 1);   // -2X
                3'b101, 3'b110: booth_term = -x32;          // -X
                default:        booth_term = 32'sd0;         // 000 / 111 -> 0
            endcase
        end
    endfunction

    // ---------------- Stage 1: input register + control valid ----------------
    reg signed [15:0] x_s1, y_s1;
    reg               v_s1;

    // ---------------- Stage 2: partial products ----------------
    reg signed [31:0] pp0, pp1, pp2, pp3, pp4, pp5, pp6, pp7;
    reg               v_s2;

    // ---------------- Stage 3: first reduction ----------------
    reg signed [31:0] sumA, sumB;
    reg               v_s3;

    // ---------------- Stage 4: final summation ----------------
    reg signed [31:0] total;
    reg               v_s4;

    // sign-extended multiplicand and the eight overlapping Booth groups of y_s1
    wire signed [31:0] x32 = {{16{x_s1[15]}}, x_s1};
    wire [2:0] g0 = { y_s1[1],  y_s1[0],  1'b0      };
    wire [2:0] g1 = { y_s1[3],  y_s1[2],  y_s1[1]   };
    wire [2:0] g2 = { y_s1[5],  y_s1[4],  y_s1[3]   };
    wire [2:0] g3 = { y_s1[7],  y_s1[6],  y_s1[5]   };
    wire [2:0] g4 = { y_s1[9],  y_s1[8],  y_s1[7]   };
    wire [2:0] g5 = { y_s1[11], y_s1[10], y_s1[9]   };
    wire [2:0] g6 = { y_s1[13], y_s1[12], y_s1[11]  };
    wire [2:0] g7 = { y_s1[15], y_s1[14], y_s1[13]  };

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            x_s1 <= 16'sd0; y_s1 <= 16'sd0; v_s1 <= 1'b0;
            pp0 <= 32'sd0; pp1 <= 32'sd0; pp2 <= 32'sd0; pp3 <= 32'sd0;
            pp4 <= 32'sd0; pp5 <= 32'sd0; pp6 <= 32'sd0; pp7 <= 32'sd0;
            v_s2 <= 1'b0;
            sumA <= 32'sd0; sumB <= 32'sd0; v_s3 <= 1'b0;
            total <= 32'sd0; v_s4 <= 1'b0;
            result <= 32'd0; done <= 1'b0;
        end else begin
            // Stage 1
            x_s1 <= X;
            y_s1 <= Y;
            v_s1 <= start;

            // Stage 2 : Booth-encode + partial-product generation (each shifted 2*i)
            pp0 <= booth_term(x32, g0) <<< 0;
            pp1 <= booth_term(x32, g1) <<< 2;
            pp2 <= booth_term(x32, g2) <<< 4;
            pp3 <= booth_term(x32, g3) <<< 6;
            pp4 <= booth_term(x32, g4) <<< 8;
            pp5 <= booth_term(x32, g5) <<< 10;
            pp6 <= booth_term(x32, g6) <<< 12;
            pp7 <= booth_term(x32, g7) <<< 14;
            v_s2 <= v_s1;

            // Stage 3 : partial-product reduction
            sumA <= pp0 + pp1 + pp2 + pp3;
            sumB <= pp4 + pp5 + pp6 + pp7;
            v_s3 <= v_s2;

            // Stage 4 : final summation
            total <= sumA + sumB;
            v_s4  <= v_s3;

            // Stage 5 : output result (held stable until next valid) + done strobe
            if (v_s4)
                result <= total;
            done <= v_s4;
        end
    end
endmodule

module restoring_division #(
    parameter WIDTH = 6
)(
    input  wire             clk,        // Clock signal
    input  wire             rst,        // Active-low asynchronous reset
    input  wire             start,      // Active-high start
    input  wire [WIDTH-1:0] dividend,   // Dividend
    input  wire [WIDTH-1:0] divisor,    // Divisor
    output reg  [WIDTH-1:0] quotient,   // Quotient
    output reg  [WIDTH-1:0] remainder,  // Remainder
    output reg              valid       // Active-high one-cycle completion strobe
);

    localparam IDLE = 2'd0,
               BUSY = 2'd1;

    reg [1:0]                 state;
    reg [WIDTH-1:0]           div_reg;    // latched divisor
    reg [WIDTH-1:0]           dvnd_reg;   // remaining dividend bits (MSB shifted out)
    reg [WIDTH:0]             rem_reg;    // WIDTH+1 bit partial remainder
    reg [WIDTH-1:0]           quot_reg;   // quotient under construction
    reg [$clog2(WIDTH+1):0]   cnt;        // iteration counter

    // One restoring-division step (combinational):
    //   shift the remainder left, bring in the next dividend MSB, then try
    //   to subtract the divisor.  A non-negative result means the divisor
    //   fits -> quotient bit 1 and keep the difference; otherwise restore.
    wire [WIDTH:0] rem_shifted = {rem_reg[WIDTH-1:0], dvnd_reg[WIDTH-1]};
    wire [WIDTH:0] sub_res     = rem_shifted - {1'b0, div_reg};
    wire           fits        = ~sub_res[WIDTH];
    wire [WIDTH:0] rem_next    = fits ? sub_res : rem_shifted;
    wire [WIDTH-1:0] quot_next = {quot_reg[WIDTH-2:0], fits};

    always @(posedge clk or negedge rst) begin
        if (!rst) begin
            state     <= IDLE;
            quotient  <= {WIDTH{1'b0}};
            remainder <= {WIDTH{1'b0}};
            valid     <= 1'b0;
            div_reg   <= {WIDTH{1'b0}};
            dvnd_reg  <= {WIDTH{1'b0}};
            rem_reg   <= {(WIDTH+1){1'b0}};
            quot_reg  <= {WIDTH{1'b0}};
            cnt       <= {($clog2(WIDTH+1)+1){1'b0}};
        end else begin
            case (state)
                IDLE: begin
                    valid <= 1'b0;
                    if (start) begin
                        div_reg  <= divisor;
                        dvnd_reg <= dividend;
                        rem_reg  <= {(WIDTH+1){1'b0}};
                        quot_reg <= {WIDTH{1'b0}};
                        cnt      <= {($clog2(WIDTH+1)+1){1'b0}};
                        state    <= BUSY;
                    end
                end
                BUSY: begin
                    rem_reg  <= rem_next;
                    quot_reg <= quot_next;
                    dvnd_reg <= {dvnd_reg[WIDTH-2:0], 1'b0};
                    cnt      <= cnt + 1'b1;
                    if (cnt == (WIDTH-1)) begin
                        // final iteration : present the result and pulse valid
                        quotient  <= quot_next;
                        remainder <= rem_next[WIDTH-1:0];
                        valid     <= 1'b1;
                        state     <= IDLE;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

endmodule

module run_length
#(
    parameter DATA_WIDTH = 8                          // Width of the output run-length counter
)
(
    input  wire                          clk,         // Clock signal
    input  wire                          reset_n,     // Active-low reset signal
    input  wire                          data_in,     // Input data stream
    output reg                           data_out,    // Output data to indicate the previous data_in
    output reg  [$clog2(DATA_WIDTH):0]   run_value,   // Output the run length value
    output reg                           valid        // Output valid flag for run length
);

    reg [$clog2(DATA_WIDTH):0] run_length;
    reg                        prev_data_in;

    // ----------------------------------------------------------------
    // Run-length counting and run_value update
    //   - matching data_in  : increment the consecutive-run counter,
    //     saturating at DATA_WIDTH (then emit the run and restart at 1)
    //   - differing data_in : a transition, emit the previous run and
    //     restart the counter at 1 for the new value
    // ----------------------------------------------------------------
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            run_length   <= 'b0;
            run_value    <= 'b0;
            prev_data_in <= 1'b0;
        end else begin
            if (data_in == prev_data_in) begin
                if (run_length >= DATA_WIDTH[$clog2(DATA_WIDTH):0]) begin
                    // saturation : emit the full run, restart at 1
                    run_value  <= run_length;
                    run_length <= 'd1;
                end else begin
                    run_length <= run_length + 'd1;
                end
            end else begin
                // transition : emit the previous run length, restart at 1
                run_value  <= run_length;
                run_length <= 'd1;
            end
            prev_data_in <= data_in;
        end
    end

    // ----------------------------------------------------------------
    // valid / data_out generation
    //   valid is HIGH on a transition OR when the run saturates at
    //   DATA_WIDTH, and LOW otherwise (one-cycle pulse behaviour).
    // ----------------------------------------------------------------
    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            valid    <= 1'b0;
            data_out <= 1'b0;
        end else begin
            if (data_in != prev_data_in) begin
                valid    <= 1'b1;
                data_out <= prev_data_in;
            end else if (run_length >= DATA_WIDTH[$clog2(DATA_WIDTH):0]) begin
                valid    <= 1'b1;
                data_out <= prev_data_in;
            end else begin
                valid    <= 1'b0;
            end
        end
    end

endmodule

module sorting_engine #(
    parameter N = 8,
    parameter WIDTH = 8
)(
    input  wire                clk,
    input  wire                rst,
    input  wire                start,
    input  wire [N*WIDTH-1:0]  in_data,
    output reg                 done,
    output reg [N*WIDTH-1:0]   out_data
);
    localparam IDLE = 2'd0,
               LOAD = 2'd1,
               SORT = 2'd2,
               DONE = 2'd3;

    reg [1:0]  state, next_state;
    reg [WIDTH-1:0] data_array [0:N-1];
    reg [$clog2(N+1)-1:0] pass_cnt;
    reg [$clog2(N/2+1)-1:0] pair_idx;

    wire [$clog2(N/2+1)-1:0] pairs_in_this_pass;
    assign pairs_in_this_pass = (pass_cnt[0] == 1'b0) ? (N/2) : ( (N/2) > 0 ? (N/2) - 1 : 0 );

    integer i;
    integer lo;
    integer hi;

    // ---- next-state (combinational) ----
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: if (start) next_state = LOAD;
            LOAD: next_state = SORT;
            SORT: if (pass_cnt >= N) next_state = DONE;
            DONE: next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end

    // ---- datapath / sequential ----
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state    <= IDLE;
            done     <= 1'b0;
            pass_cnt <= 0;
            pair_idx <= 0;
            for (i = 0; i < N; i = i + 1)
                data_array[i] <= {WIDTH{1'b0}};
            // out_data intentionally left uninitialized at reset (per spec)
        end else begin
            state <= next_state;
            done  <= 1'b0;
            case (state)
                IDLE: begin
                    if (start) begin
                        pass_cnt <= 0;
                        pair_idx <= 0;
                    end
                end
                LOAD: begin
                    for (i = 0; i < N; i = i + 1)
                        data_array[i] <= in_data[i*WIDTH +: WIDTH];
                    pass_cnt <= 0;
                    pair_idx <= 0;
                end
                SORT: begin
                    if (pass_cnt < N) begin
                        if (pairs_in_this_pass == 0) begin
                            // empty (odd) pass for very small N — just advance
                            pair_idx <= 0;
                            pass_cnt <= pass_cnt + 1'b1;
                        end else begin
                            // index of the low element of the current pair
                            if (pass_cnt[0] == 1'b0)
                                lo = pair_idx << 1;        // even pass: (0,1),(2,3)...
                            else
                                lo = (pair_idx << 1) + 1;  // odd  pass: (1,2),(3,4)...
                            hi = lo + 1;
                            // compare-and-swap (ascending: smallest toward index 0)
                            if (data_array[lo] > data_array[hi]) begin
                                data_array[lo] <= data_array[hi];
                                data_array[hi] <= data_array[lo];
                            end
                            // advance pair / pass counters (one compare-swap per cycle)
                            if (pair_idx >= (pairs_in_this_pass - 1)) begin
                                pair_idx <= 0;
                                pass_cnt <= pass_cnt + 1'b1;
                            end else begin
                                pair_idx <= pair_idx + 1'b1;
                            end
                        end
                    end
                end
                DONE: begin
                    for (i = 0; i < N; i = i + 1)
                        out_data[i*WIDTH +: WIDTH] <= data_array[i];
                    done <= 1'b1;
                end
                default: ;
            endcase
        end
    end
endmodule

module ttc_counter_lite (
    input  wire        clk,
    input  wire        reset,        // active-high synchronous reset
    input  wire [3:0]  axi_addr,
    input  wire [31:0] axi_wdata,
    input  wire        axi_write_en,
    input  wire        axi_read_en,
    output reg  [31:0] axi_rdata,
    output reg         interrupt
);
    // Register-map addresses
    localparam [3:0] ADDR_COUNT   = 4'h0,
                     ADDR_MATCH   = 4'h1,
                     ADDR_RELOAD  = 4'h2,
                     ADDR_CONTROL = 4'h3,
                     ADDR_STATUS  = 4'h4;

    reg [15:0] count;
    reg [15:0] match_value;
    reg [15:0] reload_value;

    reg        enable;
    reg        interval_mode;
    reg        interrupt_enable;

    reg        matched;   // tracks that the current match has already been seen

    wire match = enable && (count == match_value);

    // ---------------- write / counter / interrupt ----------------
    always @(posedge clk) begin
        if (reset) begin
            count            <= 16'd0;
            match_value      <= 16'd0;
            reload_value     <= 16'd0;
            enable           <= 1'b0;
            interval_mode    <= 1'b0;
            interrupt_enable <= 1'b0;
            interrupt        <= 1'b0;
            matched          <= 1'b0;
        end else begin
            // ---- counter ----
            if (enable) begin
                if (count == match_value) begin
                    if (interval_mode)
                        count <= reload_value;   // interval mode: reload on match
                    else
                        count <= match_value;    // one-shot mode: hold at match
                end else begin
                    count <= count + 16'd1;
                end
            end

            // ---- match-event bookkeeping (one-shot per match) ----
            if (match)
                matched <= 1'b1;
            else
                matched <= 1'b0;

            // ---- interrupt: set on a new match (if enabled), cleared on
            //      a write to the status register (clear has priority) ----
            if (axi_write_en && (axi_addr == ADDR_STATUS))
                interrupt <= 1'b0;
            else if (match && !matched && interrupt_enable)
                interrupt <= 1'b1;

            // ---- register writes ----
            if (axi_write_en) begin
                case (axi_addr)
                    ADDR_MATCH:   match_value  <= axi_wdata[15:0];
                    ADDR_RELOAD:  reload_value <= axi_wdata[15:0];
                    ADDR_CONTROL: begin
                        enable           <= axi_wdata[0];
                        interval_mode    <= axi_wdata[1];
                        interrupt_enable <= axi_wdata[2];
                    end
                    default: ;
                endcase
            end
        end
    end

    // ---------------- read (combinational) ----------------
    always @(*) begin
        case (axi_addr)
            ADDR_COUNT:   axi_rdata = {16'd0, count};
            ADDR_MATCH:   axi_rdata = {16'd0, match_value};
            ADDR_RELOAD:  axi_rdata = {16'd0, reload_value};
            ADDR_CONTROL: axi_rdata = {29'd0, interrupt_enable, interval_mode, enable};
            ADDR_STATUS:  axi_rdata = {31'd0, interrupt};
            default:      axi_rdata = 32'd0;
        endcase
    end

endmodule
